import zlib,struct
def png(path,w,h):
    rows=[]
    for y in range(h):
        r=bytearray([0])
        for x in range(w):
            # checkerboard-ish: alternate so top/bottom halves differ
            v=((x//4)+(y//4))%2
            r += bytes([v*255, 0, 0])
        rows.append(bytes(r))
    raw=b''.join(rows)
    def chunk(t,d):
        c=t+d
        return struct.pack('>I',len(d))+c+struct.pack('>I',zlib.crc32(c)&0xffffffff)
    ihdr=struct.pack('>IIBBBBB',w,h,8,2,0,0,0)
