// Markdown document model + parser
use serde::Serialize;

#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(tag = "type")]
pub enum Inline {
    #[serde(rename = "text")]
    Text { value: String },
    #[serde(rename = "strong")]
    Strong { value: String },
    #[serde(rename = "emphasis")]
    Emphasis { value: String },
    #[serde(rename = "code")]
    Code { value: String },
    #[serde(rename = "strikethrough")]
    Strikethrough { value: String },
    #[serde(rename = "link")]
    Link {
        text: String,
        url: String,
        title: Option<String>,
    },
    #[serde(rename = "image")]
    Image {
        alt: String,
        src: String,
        title: Option<String>,
    },
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct ListItem {
    pub checked: Option<bool>,
    pub content: String,
    pub inline: Vec<Inline>,
}

#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(tag = "type")]
pub enum Block {
    #[serde(rename = "paragraph")]
    Paragraph { content: String, inline: Vec<Inline> },
    #[serde(rename = "heading")]
    Heading {
        level: u8,
        content: String,
        inline: Vec<Inline>,
        anchor: String,
    },
    #[serde(rename = "code")]
    Code {
        language: Option<String>,
        content: String,
        start_line: usize,
        end_line: usize,
    },
    #[serde(rename = "list")]
    List {
        ordered: bool,
        items: Vec<ListItem>,
    },
    #[serde(rename = "table")]
    Table {
        headers: Vec<String>,
        alignments: Vec<String>,
        rows: Vec<Vec<String>>,
    },
    #[serde(rename = "blockquote")]
    Blockquote { content: String, blocks: Vec<Block> },
    #[serde(rename = "horizontalrule")]
    HorizontalRule,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Position {
    pub line: usize,
    pub offset: usize,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Content {
    pub raw: String,
    pub blocks: Vec<Block>,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Section {
    pub id: String,
    pub level: u8,
    pub title: String,
    pub slug: String,
    pub position: Position,
    pub content: Content,
    pub children: Vec<Section>,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Metadata {
    pub source: Option<String>,
    pub heading_count: usize,
    pub max_depth: usize,
    pub word_count: usize,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Document {
    pub metadata: Metadata,
    pub sections: Vec<Section>,
}

pub fn slugify(s: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = true;
    for ch in s.chars() {
        if ch.is_alphanumeric() {
            for c in ch.to_lowercase() {
                out.push(c);
            }
            prev_dash = false;
        } else if ch == '-' || ch == '_' {
            if !prev_dash {
                out.push('-');
                prev_dash = true;
            }
        } else {
            if !prev_dash {
                out.push('-');
                prev_dash = true;
            }
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    out
}

/// Count of whitespace separated words
pub fn count_words(s: &str) -> usize {
    s.split_whitespace().count()
}

struct RawHeading {
    level: u8,
    title: String,
    line: usize, // 1-based line index of heading text line
    start_off: usize,
    match_start: usize,
    match_end: usize, // end of the matched heading text (excluding newline)
    line_end: usize,  // offset after newline (or end of text)
    indented: bool,
}

fn find_headings(text: &str, allow_indent: bool) -> Vec<RawHeading> {
    let bytes = text.as_bytes();
    let lines: Vec<&str> = text.split('\n').collect();
    let mut out = Vec::new();
    let mut off = 0usize;
    for (idx, line) in lines.iter().enumerate() {
        let ln = idx + 1;
        let trimmed = line.trim_start_matches([' ', '\t']);
        let indent = line.len() - trimmed.len();
        let indent_only_spaces = line[..indent].chars().all(|c| c == ' ');
        let mut matched: Option<(u8, usize, usize)> = None; // level, marker_len, title_start
        if indent_only_spaces && indent <= 3 {
            let chars: Vec<char> = trimmed.chars().collect();
            let mut h = 0usize;
            while h < chars.len() && chars[h] == '#' {
                h += 1;
            }
            if h >= 1 && h <= 6 {
                // rest must be empty or start with whitespace
                let rest: String = chars[h..].iter().collect();
                if rest.is_empty() {
                    matched = Some((h as u8, h, indent + h));
                } else if rest.starts_with(' ') {
                    matched = Some((h as u8, h, indent + h));
                }
            }
        }
        // setext underline
        if matched.is_none() && !trimmed.is_empty() && !allow_indent || matched.is_none() {
            // handled later (two pass) - setext requires previous line
        }
        if let Some((level, _marker, title_start)) = matched {
            let mstart = off + indent;
            let mend = off + line.len();
            let lend = if idx + 1 < lines.len() || text.ends_with('\n') {
                off + line.len() + 1
            } else {
                off + line.len()
            };
            let title = text[mstart + level as usize..].trim().to_string();
            out.push(RawHeading {
                level: level as u8,
                title,
                line: ln,
                start_off: off,
                match_start: mstart,
                match_end: mend,
                line_end: lend,
                indented: indent > 0,
            });
        }
        off += line.len() + 1;
    }
    out
}

fn setext_level(text: &str, line_idx: usize) -> Option<u8> {
    // returns level if line `line_idx` is an underline for a heading
    let lines: Vec<&str> = text.split('\n').collect();
    if line_idx == 0 || line_idx >= lines.len() {
        return None;
    }
    let prev = lines[line_idx - 1];
    if prev.trim().is_empty() {
        return None;
    }
    let cur = lines[line_idx].trim();
    if !cur.is_empty() && cur.chars().all(|c| c == '=') {
        Some(1)
    } else if !cur.is_empty() && cur.chars().all(|c| c == '-') {
        Some(2)
    } else {
        None
    }
}
