{"command": "cd /workspace && cat > src/markdown.rs <<'RSEOF'
// Markdown document model + parser (behavior matches treemd 0.5.7)
use serde::Serialize;

#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(tag = "type")]
pub enum Inline {
    #[serde(rename = "text")]
    Text { value: String },
    #[serde(rename = "strong")]
    Strong { value: String },
    #[serde(rename = "emphasis")]
    Emphasis { value: String },
    #[serde(rename = "code")]
    Code { value: String },
    #[serde(rename = "strikethrough")]
    Strikethrough { value: String },
    #[serde(rename = "link")]
    Link {
        text: String,
        url: String,
        title: Option<String>,
    },
    #[serde(rename = "image")]
    Image {
        alt: String,
        src: String,
        title: Option<String>,
    },
}

impl Inline {
    /// plain text value of the inline element
    pub fn plain(&self) -> String {
        match self {
            Inline::Text { value }
            | Inline::Strong { value }
            | Inline::Emphasis { value }
            | Inline::Code { value }
            | Inline::Strikethrough { value } => value.clone(),
            Inline::Link { text, .. } => text.clone(),
            Inline::Image { alt, .. } => alt.clone(),
        }
    }
    /// markdown-ish rendering used for Block content
    pub fn render(&self) -> Option<String> {
        match self {
            Inline::Text { value } => Some(value.clone()),
            Inline::Strong { value } => Some(value.clone()),
            Inline::Emphasis { value } => Some(value.clone()),
            Inline::Code { value } => Some(value.clone()),
            Inline::Strikethrough { value } => Some(value.clone()),
            Inline::Link { text, url, .. } => Some(format!("[{}]({})", text, url)),
            Inline::Image { .. } => None, // special: resets accumulated content
        }
    }
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct ListItem {
    pub checked: Option<bool>,
    pub content: String,
    pub inline: Vec<Inline>,
}

#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(tag = "type")]
pub enum Block {
    #[serde(rename = "paragraph")]
    Paragraph { content: String, inline: Vec<Inline> },
    #[serde(rename = "heading")]
    Heading {
        level: u8,
        content: String,
        inline: Vec<Inline>,
        anchor: String,
    },
    #[serde(rename = "code")]
    Code {
        language: Option<String>,
        content: String,
        start_line: usize,
        end_line: usize,
    },
    #[serde(rename = "list")]
    List {
        ordered: bool,
        items: Vec<ListItem>,
    },
    #[serde(rename = "table")]
    Table {
        headers: Vec<String>,
        alignments: Vec<String>,
        rows: Vec<Vec<String>>,
    },
    #[serde(rename = "blockquote")]
    Blockquote { content: String, blocks: Vec<Block> },
    #[serde(rename = "horizontalrule")]
    HorizontalRule,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Position {
    pub line: usize,
    pub offset: usize,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Content {
    pub raw: String,
    pub blocks: Vec<Block>,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Section {
    pub id: String,
    pub level: u8,
    pub title: String,
    pub slug: String,
    pub position: Position,
    pub content: Content,
    pub children: Vec<Section>,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Metadata {
    pub source: Option<String>,
    pub heading_count: usize,
    pub max_depth: usize,
    pub word_count: usize,
}

#[derive(Clone, Debug, Default, Serialize)]
pub struct Document {
    pub metadata: Metadata,
    pub sections: Vec<Section>,
}

pub fn slugify(s: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = true;
    for ch in s.chars() {
        if ch.is_alphanumeric() {
            for c in ch.to_lowercase() {
                out.push(c);
            }
            prev_dash = false;
        } else {
            if !prev_dash {
                out.push('-');
                prev_dash = true;
            }
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    out
}

pub fn count_words(s: &str) -> usize {
    s.split_whitespace().count()
}
RSEOF
echo ok"}

