// Document / section / block parsing
use crate::markdown::*;

#[derive(Clone, Copy, Debug)]
pub struct LineInfo {
    pub start: usize,
    pub end_nl: usize, // offset after the newline (== text.len() for a final unterminated line)
    pub has_nl: bool,
}

pub struct Scan {
    pub lines: Vec<LineInfo>,
    pub text_len: usize,
}

pub fn line_infos(text: &str) -> Vec<LineInfo> {
    let mut out = Vec::new();
    let mut off = 0usize;
    for line in text.split('\n') {
        let l = line.len();
        out.push(LineInfo { start: off, end_nl: off + l + 1, has_nl: true });
        off += l + 1;
    }
    if let Some(last) = out.last_mut() {
        // last element corresponds to text after the final '\n' (empty) or the final unterminated line
        let last_start = last.start;
        if text.len() == last_start && !text.is_empty() {
            // text ends with newline: last pseudo line is empty
            last.has_nl = false;
            last.end_nl = last_start;
        } else if text.len() < last.end_nl {
            last.has_nl = false;
            last.end_nl = text.len();
        }
    }
    out
}

fn offset_of_line(lines: &[LineInfo], idx: usize) -> Option<usize> {
    lines.get(idx).map(|l| l.start)
}

#[derive(Clone, Debug)]
pub enum Head {
    Atx { level: u8, title: String, line_idx: usize, indent: usize, mstart: usize, mend: usize },
    Setext { level: u8, title: String, text_line: usize },
}

/// scan for ATX hash headings (indent <= 3 spaces) and setext headings, skipping ``` fences
pub fn find_outline_headings(text: &str, lines: &[LineInfo]) -> Vec<Head> {
    let n = lines.len();
    let mut in_fence = false;
    let mut out: Vec<Head> = Vec::new();
    for i in 0..n {
        let raw = &text[lines[i].start..lines[i].end_nl];
        let line = raw.trim_end_matches('\n');
        let tr = line.trim_start_matches([' ', '\t']);
        let indent = line.len() - tr.len();
        let indent_spaces = line[..indent].chars().all(|c| c == ' ');
        // fence toggling: only ``` fences protect against headings
        let tr2 = tr.trim_start_matches('#');
        let _ = tr2;
        if tr.starts_with("```") {
            in_fence = !in_fence;
            continue;
        }
        if in_fence {
            continue;
        }
        if indent_spaces && indent <= 3 {
            if let Some((level, rest)) = hash_level(tr) {
                let title = rest.trim().to_string();
                out.push(Head::Atx { level, title, line_idx: i, indent, mstart: lines[i].start + indent, mend: lines[i].start + line.len() });
                continue;
            }
        }
        // setext underline check for line i (underline) using preceding paragraph
        if i > 0 {
            if let Some(lvl) = underline_level(tr) {
                if let Some(pstart) = setext_paragraph_start(text, lines, i) {
                    let title = setext_title(text, lines, pstart, i);
                    out.push(Head::Setext { level: lvl, title, text_line: pstart });
                    continue;
                }
            }
        }
    }
    out.sort_by_key(|h| match h {
        Head::Atx { line_idx, .. } => (*line_idx, 0u8),
        Head::Setext { text_line, .. } => (*text_line, 1u8),
    });
    out
}

fn hash_level(tr: &str) -> Option<(u8, &str)> {
    let chars: Vec<char> = tr.chars().collect();
    let mut h = 0;
    while h < chars.len() && chars[h] == '#' {
        h += 1;
    }
    if h < 1 || h > 6 {
        return None;
    }
    let rest: String = chars[h..].iter().collect();
    if rest.is_empty() {
        return Some((h as u8, ""));
    }
    if rest.starts_with(' ') || rest.starts_with('\t') {
        return Some((h as u8, &tr[h..]));
    }
    None
}

fn underline_level(tr: &str) -> Option<u8> {
    if tr.is_empty() {
        return None;
    }
    if tr.chars().all(|c| c == '=') {
        Some(1)
    } else if tr.chars().all(|c| c == '-') {
        Some(2)
    } else {
        None
    }
}

fn is_list_marker(tr: &str) -> bool {
    if tr.starts_with("- ") || tr.starts_with("* ") || tr.starts_with("+ ") {
        return true;
    }
    if tr == "-" || tr == "*" || tr == "+" {
        return false;
    }
    let b: Vec<char> = tr.chars().collect();
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
    }
    if i > 0 && i < b.len() && (b[i] == '.' || b[i] == ')') && i + 1 < b.len() && b[i + 1] == ' ' {
        return true;
    }
    false
}

/// start line index of the "paragraph" preceding an underline at line `ul`
fn setext_paragraph_start(text: &str, lines: &[LineInfo], ul: usize) -> Option<usize> {
    let mut i = ul;
    let mut pstart = None;
    while i > 0 {
        let raw = &text[lines[i - 1].start..lines[i - 1].end_nl];
        let prev = raw.trim_end_matches('\n');
        let tr = prev.trim_start_matches([' ', '\t']);
        let indent = prev.len() - tr.len();
        let indent_spaces = prev[..indent].chars().all(|c| c == ' ');
        if tr.is_empty() {
            break;
        }
        if tr.starts_with("```") || tr.starts_with("~~~") {
            break;
        }
        if is_list_marker(tr) || tr.starts_with('>') {
            break;
        }
        if indent_spaces && indent >= 4 {
            break;
        }
        pstart = Some(i - 1);
        // stop if previous line is a hash heading line
        if indent_spaces && indent <= 3 {
            if hash_level(tr).is_some() {
                break;
            }
        }
        i -= 1;
    }
    pstart
}

fn inline_plain(s: &str) -> String {
    parse_inline(s).iter().map(|i| i.plain()).collect()
}

fn setext_title(text: &str, lines: &[LineInfo], pstart: usize, ul: usize) -> String {
    let mut s = String::new();
    for i in pstart..ul {
        let raw = &text[lines[i].start..lines[i].end_nl];
        let l = raw.trim_end_matches('\n');
        s.push_str(&inline_plain(l));
    }
    s
}

/// lines matching `^\s*(#{1,6})\s*` used to cut section content (ignores ``` fences only)
pub fn find_boundary_lines(text: &str, lines: &[LineInfo]) -> Vec<usize> {
    let mut out = Vec::new();
    let mut in_fence = false;
    for i in 0..lines.len() {
        let raw = &text[lines[i].start..lines[i].end_nl];
        let line = raw.trim_end_matches('\n');
        let tr = line.trim_start_matches([' ', '\t']);
        if tr.starts_with("```") {
            in_fence = !in_fence;
            continue;
        }
        if in_fence {
            continue;
        }
        if let Some((_, rest)) = hash_level(tr) {
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
                out.push(i);
            }
        }
    }
    out
}
