// Inline element parsing
use crate::markdown::*;

/// Parse a line of text into inline elements.
pub fn parse_inline(s: &str) -> Vec<Inline> {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut out: Vec<Inline> = Vec::new();
    let mut buf = String::new();
    let mut i = 0usize;
    macro_rules! flush {
        () => {
            if !buf.is_empty() {
                out.push(Inline::Text { value: std::mem::take(&mut buf) });
            }
        };
    }
    while i < n {
        let c = chars[i];
        match c {
            '\\' => {
                flush!();
                if i + 1 < n {
                    buf.push(chars[i + 1]);
                    i += 2;
                } else {
                    buf.push('\\');
                    i += 1;
                }
                continue;
            }
            '!' if i + 1 < n && chars[i + 1] == '[' => {
                if let Some((end, alt, src)) = scan_image(&chars, i) {
                    flush!();
                    out.push(Inline::Image { alt, src, title: None });
                    i = end;
                    continue;
                } else {
                    buf.push('!');
                    i += 1;
                    continue;
                }
            }
            '[' => {
                if let Some((end, text, url)) = scan_link(&chars, i) {
                    flush!();
                    out.push(Inline::Link { text, url, title: None });
                    i = end;
                    continue;
                } else {
                    flush!();
                    buf.push('[');
                    i += 1;
                    continue;
                }
            }
            '<' => {
                if let Some(end) = scan_html_tag(&chars, i) {
                    flush!();
                    i = end;
                    continue;
                } else {
                    flush!();
                    buf.push('<');
                    i += 1;
                    continue;
                }
            }
            '&' => {
                if let Some((end, decoded)) = scan_entity(&chars, i) {
                    flush!();
                    out.push(Inline::Text { value: decoded });
                    i = end;
                    continue;
                } else {
                    buf.push('&');
                    i += 1;
                    continue;
                }
            }
            '`' => {
                if let Some((end, val)) = scan_code(&chars, i) {
                    flush!();
                    out.push(Inline::Code { value: val });
                    i = end;
                    continue;
                } else {
                    flush!();
                    buf.push('`');
                    i += 1;
                    continue;
                }
            }
            '*' | '_' => {
                let mut run = 0;
                while i + run < n && chars[i + run] == c {
                    run += 1;
                }
                if let Some((end, inner_start, inner_end)) = find_closer(&chars, i + run, c, run) {
                    flush!();
                    let inner: String = chars[inner_start..inner_end].iter().collect();
                    let level = if run >= 2 { 2 } else { 1 };
                    let subs = parse_inline(&inner);
                    for e in subs {
                        out.push(e);
                    }
                    i = end;
                    continue;
                } else {
                    for _ in 0..run {
                        buf.push(c);
                    }
                    i += run;
                    continue;
                }
            }
            '~' => {
                let mut run = 0;
                while i + run < n && chars[i + run] == '~' {
                    run += 1;
                }
                if run >= 2 {
                    if let Some((end, inner_start, inner_end)) = find_closer(&chars, i + run, '~', 2) {
                        flush!();
                        let inner: String = chars[inner_start..inner_end].iter().collect();
                        for e in parse_inline(&inner) {
                            out.push(e);
                        }
                        i = end;
                        continue;
                    }
                }
                buf.push('~');
                i += 1;
                continue;
            }
            _ => {
                buf.push(c);
                i += 1;
            }
        }
    }
    if !buf.is_empty() {
        out.push(Inline::Text { value: buf });
    }
    out
}

/// find closing run of `c` with length >= run; returns (end_index_after_close, inner_start, inner_end)
fn find_closer(chars: &[char], from: usize, c: char, run: usize) -> Option<(usize, usize, usize)> {
    let n = chars.len();
    let mut j = from;
    while j < n {
        if chars[j] == c {
            let mut m = 0;
            while j + m < n && chars[j + m] == c {
                m += 1;
            }
            if m >= run {
                // closing consumes last `run` chars of the run
                let close_start = j + m - run;
                let inner_end = close_start;
                let end = j + m;
                if inner_end > from {
                    return Some((end, from, inner_end));
                } else {
                    return None;
                }
            }
            j += m;
        } else {
            j += 1;
        }
    }
    None
}

fn scan_code(chars: &[char], start: usize) -> Option<(usize, String)> {
    let n = chars.len();
    let mut j = start + 1;
    while j < n {
        if chars[j] == '`' {
            let v: String = chars[start + 1..j].iter().collect();
            return Some((j + 1, v));
        }
        j += 1;
    }
    None
}

fn scan_link(chars: &[char], start: usize) -> Option<(usize, String, String)> {
    let n = chars.len();
    // find ']('
    let mut j = start + 1;
    let mut text_end = None;
    while j < n {
        if chars[j] == ']' {
            text_end = Some(j);
            break;
        }
        j += 1;
    }
    let te = text_end?;
    if te + 1 < n && chars[te + 1] == '(' {
        let mut k = te + 2;
        while k < n && chars[k] != ')' {
            k += 1;
        }
        if k < n {
            let text: String = chars[start + 1..te].iter().collect();
            let url: String = chars[te + 2..k].iter().collect();
            return Some((k + 1, text, url));
        }
    }
    None
}

fn scan_image(chars: &[char], start: usize) -> Option<(usize, String, String)> {
    let (end, text, url) = scan_link(chars, start + 1)?;
    Some((end, text, url))
}

fn scan_html_tag(chars: &[char], start: usize) -> Option<usize> {
    let n = chars.len();
    let mut j = start + 1;
    while j < n {
        if chars[j] == '>' {
            return Some(j + 1);
        }
        if chars[j] == '<' {
            return None;
        }
        j += 1;
    }
    None
}

fn scan_entity(chars: &[char], start: usize) -> Option<(usize, String)> {
    let n = chars.len();
    let mut j = start + 1;
    let mut digits = false;
    let mut alpha = false;
    let mut alpha_str = String::new();
    while j < n {
        let c = chars[j];
        if c == ';' {
            if digits && !alpha && j > start + 1 && chars[start + 1] == '#' {
                let num: String = chars[start + 2..j].iter().collect();
                if let Ok(v) = num.parse::<u32>() {
                    if let Some(ch) = char::from_u32(v) {
                        return Some((j + 1, ch.to_string()));
                    }
                }
                return None;
            }
            if alpha {
                let name = alpha_str.to_lowercase();
                let rep = match name.as_str() {
                    "amp" => "&",
                    "lt" => "<",
                    "gt" => ">",
                    "quot" => "\"",
                    "apos" => "'",
                    "nbsp" => "\u{a0}",
                    "copy" => "\u{a9}",
                    "hellip" => "\u{2026}",
                    "mdash" => "\u{2014}",
                    "ndash" => "\u{2013}",
                    "larr" => "\u{2190}",
