        out.push(Inline::Text { value: buf });
    }
    out
}

/// find closing run of `c` with length >= run; returns (end_index_after_close, inner_start, inner_end)
fn find_closer(chars: &[char], from: usize, c: char, run: usize) -> Option<(usize, usize, usize)> {
    let n = chars.len();
    let mut j = from;
    while j < n {
        if chars[j] == c {
            let mut m = 0;
            while j + m < n && chars[j + m] == c {
                m += 1;
            }
            if m >= run {
                // closing consumes last `run` chars of the run
                let close_start = j + m - run;
                let inner_end = close_start;
                let end = j + m;
                if inner_end > from {
                    return Some((end, from, inner_end));
                } else {
                    return None;
                }
            }
            j += m;
        } else {
            j += 1;
        }
    }
    None
}

fn scan_code(chars: &[char], start: usize) -> Option<(usize, String)> {
    let n = chars.len();
    let mut j = start + 1;
    while j < n {
        if chars[j] == '`' {
            let v: String = chars[start + 1..j].iter().collect();
            return Some((j + 1, v));
        }
        j += 1;
    }
    None
}

fn scan_link(chars: &[char], start: usize) -> Option<(usize, String, String)> {
    let n = chars.len();
    // find ']('
    let mut j = start + 1;
    let mut text_end = None;
    while j < n {
        if chars[j] == ']' {
            text_end = Some(j);
            break;
        }
        j += 1;
    }
    let te = text_end?;
    if te + 1 < n && chars[te + 1] == '(' {
        let mut k = te + 2;
        while k < n && chars[k] != ')' {
            k += 1;
        }
        if k < n {
            let text: String = chars[start + 1..te].iter().collect();
            let url: String = chars[te + 2..k].iter().collect();
            return Some((k + 1, text, url));
        }
    }
    None
}

fn scan_image(chars: &[char], start: usize) -> Option<(usize, String, String)> {
    let (end, text, url) = scan_link(chars, start + 1)?;
    Some((end, text, url))
}

fn scan_html_tag(chars: &[char], start: usize) -> Option<usize> {
    let n = chars.len();
    let mut j = start + 1;
    while j < n {
        if chars[j] == '>' {
            return Some(j + 1);
        }
        if chars[j] == '<' {
            return None;
        }
        j += 1;
    }
    None
}

