                let num: String = chars[start + 2..j].iter().collect();
                if let Ok(v) = num.parse::<u32>() {
                    if let Some(ch) = char::from_u32(v) {
                        return Some((j + 1, ch.to_string()));
                    }
                }
                return None;
            }
            if alpha {
                let name = alpha_str.to_lowercase();
                let rep = match name.as_str() {
                    "amp" => "&",
                    "lt" => "<",
                    "gt" => ">",
                    "quot" => "\"",
                    "apos" => "'",
                    "nbsp" => "\u{a0}",
                    "copy" => "\u{a9}",
                    "hellip" => "\u{2026}",
                    "mdash" => "\u{2014}",
                    "ndash" => "\u{2013}",
                    "larr" => "\u{2190}",
                    "rarr" => "\u{2192}",
                    "times" => "\u{d7}",
                    "divide" => "\u{f7}",
                    _ => {
                        return None;
                    }
                };
                return Some((j + 1, rep.to_string()));
            }
            return None;
        }
        if c.is_ascii_digit() {
            digits = true;
            j += 1;
            continue;
        }
        if c.is_ascii_alphabetic() {
            alpha = true;
            alpha_str.push(c);
            j += 1;
            continue;
        }
        return None;
    }
    None
}
