// Block parsing for a section's content
use crate::inline::parse_inline;
use crate::markdown::*;

pub fn is_fence_open(line: &str) -> Option<(char, usize)> {
    let tr = line.trim_start_matches([' ', '\t']);
    let chars: Vec<char> = tr.chars().collect();
    if chars.is_empty() {
        return None;
    }
    let c = chars[0];
    if c != '`' && c != '~' {
        return None;
    }
    let mut n = 0;
    while n < chars.len() && chars[n] == c {
        n += 1;
    }
    if n >= 3 {
        Some((c, n))
    } else {
        None
    }
}

fn fence_closes(line: &str, marker: char, len: usize) -> bool {
    let tr = line.trim_start_matches([' ', '\t']);
    let chars: Vec<char> = tr.chars().collect();
    if chars.len() < len {
        return false;
    }
    for i in 0..len {
        if chars[i] != marker {
            return false;
        }
    }
    let rest: String = chars[len..].iter().collect();
    rest.trim().is_empty()
}

fn is_blank(line: &str) -> bool {
    line.trim().is_empty()
}

fn list_marker_of(line: &str) -> Option<(bool, Option<bool>, usize)> {
    // returns (ordered, checked, marker_end_offset_in_line)
    let tr = line.trim_start_matches([' ', '\t']);
    let indent = line.len() - tr.len();
    let chars: Vec<char> = tr.chars().collect();
    if chars.is_empty() {
        return None;
    }
    if chars[0] == '-' || chars[0] == '*' || chars[0] == '+' {
        if chars.len() == 1 {
            return None;
        }
        if chars[1] == ' ' {
            // task list?
            let rest: String = chars[2..].iter().collect();
            if rest.starts_with("[ ]") {
                return Some((false, Some(false), indent + 5));
            }
            if rest.starts_with("[x]") || rest.starts_with("[X]") {
                return Some((false, Some(true), indent + 5));
            }
            return Some((false, None, indent + 2));
        }
        return None;
    }
    let mut i = 0;
    while i < chars.len() && chars[i].is_ascii_digit() {
        i += 1;
    }
    if i > 0 && i < chars.len() && (chars[i] == '.' || chars[i] == ')') {
        if i + 1 < chars.len() && chars[i + 1] == ' ' {
            return Some((true, None, indent + i + 2));
        }
    }
    None
}

fn cell_align(cell: &str) -> &'static str {
    let c = cell.trim();
    if c.starts_with(':') && c.ends_with(':') && c.len() > 1 {
        "center"
    } else if c.starts_with(':') {
        "left"
    } else if c.ends_with(':') {
        "right"
    } else {
        "none"
    }
}

fn is_table_sep(cell: &str) -> bool {
    let c = cell.trim();
    if c.is_empty() {
        return false;
    }
    let b: Vec<char> = c.chars().collect();
    let mut i = 0;
    if b[i] == ':' {
        i += 1;
    }
    let mut dashes = 0;
    while i < b.len() && b[i] == '-' {
        i += 1;
        dashes += 1;
    }
    if i < b.len() && b[i] == ':' {
        i += 1;
    }
    dashes >= 1 && i == b.len()
}

fn split_row(line: &str) -> Vec<String> {
    let s = line.trim();
    let s = s.strip_prefix('|').unwrap_or(s);
    let s = s.strip_suffix('|').unwrap_or(s);
    s.split('|').map(|c| c.trim().to_string()).collect()
}

fn is_table_row(line: &str) -> bool {
    let t = line.trim();
    t.starts_with('|') && t.ends_with('|') && t.len() >= 2
}

pub fn parse_blocks(content: &str, sec_line: usize) -> Vec<Block> {
    let lines: Vec<&str> = content.split('\n').collect();
    let mut blocks: Vec<Block> = Vec::new();
    let mut i = 0usize;
    let n = lines.len();
    // track whether the previous non-blank line is a paragraph line (for setext)
    let mut prev_para_lines: Vec<String> = Vec::new();
    while i < n {
        let line = lines[i];
        if is_blank(line) {
            i += 1;
            prev_para_lines.clear();
            continue;
        }
        if let Some((marker, _len)) = is_fence_open(line) {
            let tr = line.trim_start_matches([' ', '\t']);
            let lang_part = tr[3..].trim();
            let language = if lang_part.is_empty() { None } else { Some(lang_part.to_string()) };
            let mut body: Vec<String> = Vec::new();
            let mut j = i + 1;
            while j < n && !fence_closes(lines[j], marker, 3) {
                body.push(lines[j].to_string());
                j += 1;
            }
            let code_content = body.join("\n");
            blocks.push(Block::Code {
                language,
                content: code_content,
                start_line: sec_line,
                end_line: sec_line,
            });
            i = if j < n { j + 1 } else { j };
            prev_para_lines.clear();
            continue;
        }
        // setext heading: underline and previous paragraph line
        let tr = line.trim_start_matches([' ', '\t']);
        if !prev_para_lines.is_empty() {
            if let Some(lvl) = underline_level(tr) {
                let text = prev_para_lines.join("");
                blocks.push(Block::Heading {
                    level: lvl,
                    inline: parse_inline(&text),
                    content: text.clone(),
                    anchor: slugify(&text),
                });
                i += 1;
                prev_para_lines.clear();
                continue;
            }
        }
        // thematic break
        if (tr.chars().all(|c| c == '-') || tr.chars().all(|c| c == '*') || tr.chars().all(|c| c == '_'))
            && !tr.is_empty()
        {
            if prev_para_lines.is_empty() {
                blocks.push(Block::HorizontalRule);
                i += 1;
                continue;
            } else if tr.chars().all(|c| c == '-') {
                // handled above as setext
            } else {
                blocks.push(Block::HorizontalRule);
                i += 1;
                prev_para_lines.clear();
                continue;
            }
        }
        // list
        if let Some((ordered, checked, mend)) = list_marker_of(line) {
            let mut items: Vec<ListItem> = Vec::new();
            while i < n {
                let l = lines[i];
                if is_blank(l) {
                    break;
                }
                if let Some((_o, ch, m2)) = list_marker_of(l) {
                    let rest = l[m2.min(l.len())..].to_string();
                    items.push(ListItem { checked: ch, content: rest, inline: parse_inline(&rest) });
                    i += 1;
                    // continuation / nested lines
                    while i < n {
                        let c = lines[i];
                        if is_blank(c) {
                            break;
                        }
                        if list_marker_of(c).is_some() {
                            if c.trim_start_matches([' ', '\t']).len() < l.trim_start_matches([' ', '\t']).len() {
                                break;
                            }
                            // nested list line: append with newline
                            let inner = strip_marker(c);
