    }
    if chars[0] == '-' || chars[0] == '*' || chars[0] == '+' {
        if chars.len() == 1 {
            return None;
        }
        if chars[1] == ' ' {
            // task list?
            let rest: String = chars[2..].iter().collect();
            if rest.starts_with("[ ]") {
