                        i += 1;
                    }
                } else {
                    break;
                }
            }
            blocks.push(Block::List { ordered, items });
            prev_para_lines.clear();
            continue;
        }
        // blockquote
        if tr.starts_with('>') {
            let mut inner: Vec<String> = Vec::new();
            while i < n && !is_blank(lines[i]) {
                let l = lines[i];
                let t = l.trim_start_matches([' ', '\t']);
                if !t.starts_with('>') {
                    break;
                }
                let mut body = &t[1..];
                if body.starts_with(' ') {
                    body = &body[1..];
                }
                if !body.trim().is_empty() {
                    inner.push(body.to_string());
                }
                i += 1;
            }
            let joined: String = inner.join("");
            let bl = parse_blocks(&joined, sec_line);
            let content_str = bl
                .iter()
                .map(|b| match b {
                    Block::Paragraph { content, .. } => content.clone(),
                    Block::Heading { content, .. } => content.clone(),
                    Block::Code { content, .. } => content.clone(),
                    Block::List { items, .. } => items.iter().map(|it| it.content.clone()).collect::<String>(),
                    Block::Table { .. } => String::new(),
                    Block::Blockquote { content, .. } => content.clone(),
                    Block::HorizontalRule => String::new(),
                })
                .collect::<Vec<_>>()
                .join("");
            blocks.push(Block::Blockquote { content: content_str, blocks: bl });
            prev_para_lines.clear();
            continue;
        }
        // table
        if is_table_row(line) {
            let headers = split_row(line);
            if i + 1 < n && is_table_row(lines[i + 1]) {
                let sep = split_row(lines[i + 1]);
                if sep.len() == headers.len() && sep.iter().all(|c| is_table_sep(c)) {
                    let alignments: Vec<String> = sep.iter().map(|c| cell_align(c).to_string()).collect();
                    let mut rows: Vec<Vec<String>> = Vec::new();
                    let mut j = i + 2;
                    while j < n && is_table_row(lines[j]) && !is_blank(lines[j]) {
                        let mut cells = split_row(lines[j]);
                        while cells.len() < headers.len() {
                            cells.push(String::new());
                        }
                        cells.truncate(headers.len());
                        rows.push(cells);
                        j += 1;
                    }
                    blocks.push(Block::Table { headers, alignments, rows });
                    i = j;
                    prev_para_lines.clear();
                    continue;
                }
            }
        }
        // paragraph
        let mut para: Vec<String> = Vec::new();
        while i < n && !is_blank(lines[i]) {
            let l = lines[i];
            if let Some((marker, _)) = is_fence_open(l) {
                let _ = marker;
                break;
            }
            let t = l.trim_start_matches([' ', '\t']);
            if list_marker_of(l).is_some() || t.starts_with('>') || is_table_row(l) {
                break;
            }
            para.push(t.to_string());
            i += 1;
        }
        if !para.is_empty() {
            let mut inline: Vec<Inline> = Vec::new();
            for (k, p) in para.iter().enumerate() {
                if k > 0 {
                    inline.push(Inline::Text { value: " ".to_string() });
                }
                inline.extend(parse_inline(p));
            }
            let mut content_s = String::new();
            for e in &inline {
                match e {
                    Inline::Image { alt, src, .. } => {
                        content_s = format!("![{}]({})", alt, src);
                    }
                    _ => {
                        if let Some(r) = e.render() {
                            content_s.push_str(&r);
                        }
                    }
                }
            }
            blocks.push(Block::Paragraph { content: content_s, inline });
            prev_para_lines = para.clone();
        }
    }
    blocks
}

fn strip_marker(line: &str) -> String {
    if let Some((_o, _c, m)) = list_marker_of(line) {
        let chars: Vec<char> = line.chars().collect();
        // marker end counted in chars from line start
        let byte_idx = chars[..m.min(chars.len())].iter().map(|c| c.len_utf8()).sum();
        line[byte_idx..].to_string()
    } else {
        line.to_string()
    }
}
