                }
                let pre = &text[..lines[idx].start];
                if pre.trim().is_empty() {
                    return Document { metadata: Metadata { source: source.map(|s| s.to_string()), ..Default::default() }, sections: vec![] };
                }
                let prefixed = format!("# Input\n\n{}", text);
                let mut d = build_document(&prefixed, source, depth + 1);
                d.metadata.word_count = count_words(&prefixed);
                return d;
            }
            None => {
                let prefixed = format!("# Input\n\n{}", text);
                let mut d = build_document(&prefixed, source, depth + 1);
                d.metadata.word_count = count_words(&prefixed);
                return d;
            }
        }
    }
    let boundaries = boundary_offsets(text, &lines);
