                } else {
                    let rest = &text[*mend..];
                    let ws = rest.starts_with(' ') || rest.starts_with('\t');
                    let cstart = if ws { *mend } else { *mstart };
                    (*mstart, cstart, ws)
                };
                let _ = indent;
                let (cs2, ce) = content_range(text, &lines, &boundaries, content_start);
                built.push((BuiltHeading {
                    level: *level,
                    title: title.clone(),
                    line_idx: *line_idx,
                    content_start: cs2,
                    content_start_line: cs_line,
                    indented: *indent > 0,
                    mstart: *mstart,
                    mend: *mend,
                    has_nl_after: has_nl,
                    ws_after_marker: ws_after,
                }, cs2, ce));
                let _ = pos_off;
            }
            Head::Setext { level, title, text_line } => {
                let cs_line = text_line + 1;
                let cs = lines[cs_line].start;
                let (cs2, ce) = content_range(text, &lines, &boundaries, cs);
