        let raw = text[cs..ce.min(text.len())].trim().to_string();
        let pos_line = bh.line_idx + 2 + if bh.indented { 1 } else { 0 };
        let pos_off = if bh.has_nl_after {
            lines[bh.line_idx + 1].start
        } else {
            bh.mstart
        };
        let blocks = parse_blocks(&raw, pos_line);
        let mut sec = Section {
            id: slugify(&bh.title),
            level: bh.level,
            title: bh.title.clone(),
            slug: slugify(&bh.title),
            position: Position { line: pos_line, offset: pos_off },
            content: Content { raw, blocks },
            children: Vec::new(),
        };
        let _ = idx;
        while let Some(f) = stack.last() {
            if f.level >= bh.level {
                let f = stack.pop().unwrap();
                if let Some(p) = stack.last_mut() {
                    p.sec.children.push(f.sec);
                } else {
                    sections.push(f.sec);
                }
            } else {
                break;
            }
        }
        stack.push(Frame { level: bh.level, sec });
        max_depth = max_depth.max(stack.len());
    }
    while let Some(f) = stack.pop() {
        if let Some(p) = stack.last_mut() {
            p.sec.children.push(f.sec);
        } else {
            sections.push(f.sec);
        }
    }
    fn count(s: &Section) -> usize {
        1 + s.children.iter().map(count).sum::<usize>()
    }
    let heading_count = sections.iter().map(count).sum();
    Document {
        metadata: Metadata {
            source: source.map(|s| s.to_string()),
            heading_count,
            max_depth,
            word_count: count_words(text),
        },
        sections,
    }
}

fn first_loose_hash(text: &str, lines: &[LineInfo]) -> Option<(usize, usize)> {
    for i in 0..lines.len() {
        let raw = &text[lines[i].start..lines[i].end_nl];
        let line = raw.trim_end_matches('\n');
        let tr = line.trim_start_matches([' ', '\t']);
        let indent = line.len() - tr.len();
        if let Some((_, rest)) = crate::parse::hash_level_pub(tr) {
            if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
                return Some((i, indent));
            }
        }
    }
    None
}
