    let mut flat = Vec::new();
    for s in &doc.sections {
        walk_sections(s, &mut flat, 0);
    }
    // exact match first
    for (_d, s) in &flat {
        if s.title.to_lowercase() == target {
            return Some(extract_section(&doc.raw_text, s));
        }
    }
    // slug match
    for (_d, s) in &flat {
        if s.slug == crate::markdown::slugify(name) {
            return Some(extract_section(&doc.raw_text, s));
        }
    }
    // contains
    for (_d, s) in &flat {
        if s.title.to_lowercase().contains(&target) {
            return Some(extract_section(&doc.raw_text, s));
        }
    }
    None
}

fn extract_section(raw: &str, s: &Section) -> String {
    // from heading line to next heading of same or higher level
    let lines: Vec<&str> = raw.split('\n').collect();
    let start = s.position.line.saturating_sub(2); // 0-based heading line
    let mut end = lines.len();
    // find the next heading with level <= s.level
    let mut off = 0usize;
    let mut found = false;
    for (i, l) in lines.iter().enumerate() {
        let tr = l.trim_start_matches([' ', '\t']);
        let indent = l.len() - tr.len();
        let mut lvl = None;
        if indent <= 3 && l[..indent].chars().all(|c| c == ' ') {
            let mut h = 0;
            let ch: Vec<char> = tr.chars().collect();
            while h < ch.len() && ch[h] == '#' {
                h += 1;
            }
            if h >= 1 && h <= 6 {
                let rest: String = ch[h..].iter().collect();
                if rest.is_empty() || rest.starts_with(' ') {
                    lvl = Some(h as u8);
                }
            }
        }
        if let Some(lv) = lvl {
            if i > start && lv <= s.level {
                end = i;
                found = true;
                break;
            }
        }
        let _ = off;
        off += l.len() + 1;
    }
    let _ = found;
    let slice = lines[start.min(lines.len())..end.min(lines.len())].join("\n");
    let trimmed = slice.trim();
    format!("{}\n", trimmed)
}

pub fn document_json(doc: &Document) -> String {
    serde_json::to_string_pretty(&serde_json::json!({"document": doc})).unwrap_or_default()
}
