{"command": "cd /workspace && cat > src/query.rs <<'RSEOF'
// treemd Query Language (tql)
use crate::document::*;
use crate::markdown::*;

#[derive(Clone, Debug, PartialEq)]
pub enum Prop {
    All,
    Heading,
    H(u8),
    Code,
    Link,
    Img,
    Table,
    List,
    Blockquote,
    Doc,
}

#[derive(Clone, Debug)]
pub enum Filter {
    None,
    Fuzzy(String),
    Exact(String),
    Index(i64),
    Range(Option<i64>, Option<i64>),
    LinkKind(String),
}

#[derive(Clone, Debug)]
pub enum Ast {
    Select(Prop, Filter),
    Collect(Box<Ast>),
    Pipe(Box<Ast>, Func),
    Hierarchy(Box<Ast>, bool, Box<Ast>), // child, descendants
    Func(Func),
}

#[derive(Clone, Debug)]
pub enum Func {
    Name(String),
    Call(String, Vec<String>),
}

#[derive(Clone, Debug, Default)]
pub struct QueryResult {
    pub values: Vec<Val>,
    pub doc: Option<Document>,
    pub error: Option<QError>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Val {
    Elem(usize),
    Str(String),
    Num(f64),
    Bool(bool),
    Arr(Vec<Val>),
    Obj(Vec<(String, Val)>),
    Doc,
    Null,
}

#[derive(Debug)]
pub struct QError {
    pub kind: ErrKind,
    pub line: String,
    pub col: usize,
    pub span: usize,
}

#[derive(Debug, PartialEq)]
pub enum ErrKind {
    UnexpectedChar(String, String),
    UnexpectedToken(String, String),
    ExpectedExpr,
    ExpectedChar(String),
    ExpectedEnd(String),
    UnterminatedString,
    InvalidFilter,
    UnknownFunc(String, Option<String>),
    UnknownProp(String),
    UnknownFormat(String),
    Other(String),
}

impl QError {
    pub fn message(&self) -> String {
        use ErrKind::*;
        match &self.kind {
            UnexpectedChar(c, help) => format!(
                "error: Unexpected character '{}'\n  --> query\n  |\n1 | {}\n{}  ^  {}\n  = help: {}\n",
                c,
                self.line,
                " ".repeat(3 + self.col),
                "unexpected character",
                help
            ),
            UnexpectedToken(c, extra) => {
                let extra = if c == "end of input" {
                    "  unexpected token".to_string()
                } else {
                    format!("  unexpected token")
                };
                let _ = extra;
                let mark = if c == "end of input" { " ".repeat(self.span.max(1)) } else { "^".repeat(self.span.max(1)) };
                format!(
                    "error: Expected expression, found {}\n  --> query\n  |\n1 | {}\n{}{}  unexpected token\n",
                    c, self.line, " ".repeat(3 + self.col), mark
                )
            }
            ExpectedExpr => format!(
                "error: Expected expression, found end of input\n  --> query\n  |\n1 | {}\n{}^  unexpected token\n",
                self.line,
                " ".repeat(3 + self.line.len())
            ),
            ExpectedChar(c) => format!(
                "error: Expected '{}', found {}\n  --> query\n  |\n1 | {}\n{}^  unexpected token\n",
                c,
                if self.col >= self.line.len() { "end of input".to_string() } else { format!("'{}'", &self.line[self.col..].chars().next().unwrap()) },
                self.line,
                " ".repeat(3 + self.col)
            ),
            ExpectedEnd(found) => format!(
                "error: Expected end of query, found '{}'\n  --> query\n  |\n1 | {}\n{}^  unexpected token\n",
                found, self.line, " ".repeat(3 + self.col)
            ),
            UnterminatedString => format!(
                "error: Unterminated string literal\n  --> query\n  |\n1 | {}\n{}{}  string not closed\n",
                self.line,
                " ".repeat(3 + self.col),
                "^".repeat(self.span.max(1))
            ),
            InvalidFilter => format!(
                "error: Invalid filter: expected filter pattern or index\n  --> query\n  |\n1 | {}\n{}^  invalid filter\n",
                self.line,
                " ".repeat(3 + self.col)
            ),
            UnknownFunc(name, sugg) => match sugg {
                Some(s) => format!("error: Unknown function '{}'\n  |\n  = help: did you mean '{}'?\n", name, s),
                None => format!("error: Unknown function '{}'\n", name),
            },
            UnknownProp(p) => format!("error: Property '{}' not found on document\n\n", p),
            UnknownFormat(f) => format!("Error: Unknown output format: {}\n", f),
            Other(m) => format!("error: {}\n", m),
        }
    }
}
RSEOF
echo ok"}

