// Query parser
use crate::query::*;

pub struct P<'a> {
    pub s: Vec<char>,
    pub i: usize,
    pub line: String,
    pub _ph: std::marker::PhantomData<&'a ()>,
}

pub fn parse_query(src: &str) -> Result<Ast, QError> {
    let mut p = P { s: src.chars().collect(), i: 0, line: src.to_string(), _ph: std::marker::PhantomData };
    let ast = p.parse_expr()?;
    p.skip_ws();
    if p.i < p.s.len() {
        let c = p.s[p.i];
        return Err(QError {
            kind: ErrKind::ExpectedEnd(c.to_string()),
            line: src.to_string(),
            col: p.i,
            span: 1,
        });
    }
    Ok(ast)
}

impl<'a> P<'a> {
    fn peek(&self) -> Option<char> {
        self.s.get(self.i).copied()
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn err_here(&self, kind: ErrKind) -> QError {
        QError { kind, line: self.line.clone(), col: self.i, span: 1 }
    }
    fn ident(&mut self) -> Option<String> {
        let start = self.i;
        while let Some(c) = self.peek() {
            if c.is_alphanumeric() || c == '_' {
                self.i += 1;
            } else {
                break;
            }
        }
        if self.i > start {
            Some(self.s[start..self.i].iter().collect())
        } else {
            None
        }
    }
    fn number(&mut self) -> Option<i64> {
        let start = self.i;
        if self.peek() == Some('-') {
            self.i += 1;
        }
        let mut any = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.i += 1;
                any = true;
            } else {
                break;
            }
        }
        if !any {
            self.i = start;
            return None;
        }
        let s: String = self.s[start..self.i].iter().collect();
        s.parse::<i64>().ok()
    }

    pub fn parse_expr(&mut self) -> Result<Ast, QError> {
        self.skip_ws();
        match self.peek() {
            None => Err(self.err_here(ErrKind::ExpectedExpr)),
            Some('[') => {
                self.i += 1;
                let inner = self.parse_expr()?;
                self.skip_ws();
                if self.peek() != Some(']') {
                    return Err(self.err_here(ErrKind::ExpectedChar("]".to_string())));
                }
                self.i += 1;
                Ok(self.parse_tail(Ast::Collect(Box::new(inner))))
            }
            Some('.') => {
                self.i += 1;
                self.skip_ws();
                if self.peek() == Some('.') && self.i + 1 < self.s.len() {
                    // ".." ? treat as unexpected
                }
                if self.peek().map(|c| c.is_alphanumeric() || c == '_') == Some(true) {
                    let name = self.ident().unwrap();
                    let prop = parse_prop(&name)?;
                    let filt = self.parse_filter()?;
                    Ok(self.parse_tail(Ast::Select(prop, filt)))
                } else {
                    // bare '.' = document
                    Ok(self.parse_tail(Ast::Select(Prop::Doc, Filter::None)))
                }
            }
            Some(c) if c.is_alphanumeric() || c == '_' => {
                let name = self.ident().unwrap();
                // function call at top level? e.g. "not"
                Err(self.err_here(ErrKind::UnknownFunc(
                    name.clone(),
                    suggest(&name),
                )))
            }
            Some(c) => Err(self.err_here(ErrKind::UnexpectedChar(
                c.to_string(),
                if c == '=' { "Use '==' for equality comparison".to_string() } else { String::new() },
            ))),
        }
    }

    fn parse_filter(&mut self) -> Result<Filter, QError> {
        self.skip_ws();
        if self.peek() != Some('[') {
            return Ok(Filter::None);
        }
        self.i += 1;
        self.skip_ws();
        if self.peek() == Some(']') {
            self.i += 1;
            return Ok(Filter::None);
        }
        // string?
        if self.peek() == Some('"') {
            let s = self.string()?;
            self.skip_ws();
            if self.peek() != Some(']') {
                return Err(self.err_here(ErrKind::ExpectedChar("]".to_string())));
            }
            self.i += 1;
            return Ok(Filter::Exact(s));
        }
        // number / range
        let start = self.i;
        let first = self.number();
        self.skip_ws();
        match self.peek() {
            Some(']') => {
                self.i += 1;
                match first {
                    Some(n) => Ok(Filter::Index(n)),
                    None => Err(self.err_here(ErrKind::InvalidFilter)),
                }
            }
            Some(':') => {
                self.i += 1;
                self.skip_ws();
                let second = self.number();
                self.skip_ws();
                if self.peek() != Some(']') {
                    return Err(self.err_here(ErrKind::ExpectedChar("]".to_string())));
                }
                self.i += 1;
                Ok(Filter::Range(first, second))
            }
            _ => {
                // fuzzy text filter
                self.i = start;
                let mut chars = Vec::new();
                while let Some(c) = self.peek() {
                    if c == ']' {
                        break;
                    }
                    chars.push(c);
                    self.i += 1;
                }
                if self.peek() != Some(']') {
                    return Err(self.err_here(ErrKind::ExpectedChar("]".to_string())));
                }
                self.i += 1;
                let txt: String = chars.iter().collect();
                let t = txt.trim().to_string();
                if t.is_empty() {
                    return Ok(Filter::None);
                }
                Ok(Filter::Fuzzy(t))
            }
        }
    }

    fn string(&mut self) -> Result<String, QError> {
        // assumes current char is '"'
        let start = self.i;
        self.i += 1;
        let mut out = String::new();
        while let Some(c) = self.peek() {
            if c == '\\' {
                if let Some(n) = self.s.get(self.i + 1) {
                    out.push(*n);
                    self.i += 2;
                    continue;
                }
            }
            if c == '"' {
                self.i += 1;
                return Ok(out);
            }
            out.push(c);
            self.i += 1;
        }
        Err(QError {
            kind: ErrKind::UnterminatedString,
            line: self.line.clone(),
            col: start,
            span: 2,
        })
    }

    fn parse_tail(&mut self, ast: Ast) -> Result<Ast, QError> {
        loop {
            self.skip_ws();
            match self.peek() {
                Some('|') => {
                    self.i += 1;
                    self.skip_ws();
                    if self.peek().is_none() {
                        return Err(QError {
                            kind: ErrKind::UnexpectedToken("end of input".to_string(), String::new()),
                            line: self.line.clone(),
                            col: self.i,
                            span: 1,
                        });
                    }
                    let f = self.parse_func()?;
                    return self.parse_tail(Ast::Pipe(Box::new(ast), f));
                }
                Some('>') => {
                    self.i += 1;
                    let desc = if self.peek() == Some('>') {
                        self.i += 1;
                        true
                    } else {
                        false
                    };
                    self.skip_ws();
                    if self.peek() != Some('.') {
                        return Err(self.err_here(ErrKind::ExpectedExpr));
                    }
                    self.i += 1;
                    self.skip_ws();
                    let name = match self.ident() {
                        Some(n) => n,
                        None => return Err(self.err_here(ErrKind::ExpectedExpr)),
                    };
                    let prop = parse_prop(&name)?;
                    let filt = self.parse_filter()?;
                    let right = Ast::Select(prop, filt);
                    return self.parse_tail(Ast::Hierarchy(Box::new(ast), desc, Box::new(right)));
                }
                None => return Ok(ast),
                Some(_) => {
                    return Ok(ast);
                }
            }
        }
    }

    fn parse_func(&mut self) -> Result<Func, QError> {
        self.skip_ws();
        let name = match self.ident() {
            Some(n) => n,
            None => {
                let c = self.peek();
                return Err(self.err_here(ErrKind::UnexpectedToken(
                    match c {
                        None => "end of input".to_string(),
                        Some(ch) => format!("'{}'", ch),
                    },
                    String::new(),
                )));
            }
        };
        self.skip_ws();
        if self.peek() == Some('(') {
            self.i += 1;
            self.skip_ws();
            let mut args: Vec<String> = Vec::new();
            if self.peek() == Some(')') {
                self.i += 1;
                return Ok(Func::Call(name, args));
            }
            loop {
                self.skip_ws();
                let arg = if self.peek() == Some('"') {
                    self.string()?
                } else {
                    let start = self.i;
                    while let Some(c) = self.peek() {
                        if c == ',' || c == ')' {
                            break;
                        }
                        self.i += 1;
                    }
                    self.s[start..self.i].iter().collect::<String>().trim().to_string()
                };
                args.push(arg);
                self.skip_ws();
                match self.peek() {
                    Some(',') => {
                        self.i += 1;
                        continue;
                    }
                    Some(')') => {
                        self.i += 1;
                        break;
                    }
                    _ => {
                        let c = self.peek();
                        return Err(QError {
                            kind: ErrKind::UnexpectedToken(
                                match c {
                                    None => "end of input".to_string(),
                                    Some(ch) => format!("'{}'", ch),
                                },
                                String::new(),
                            ),
                            line: self.line.clone(),
                            col: self.i,
                            span: 1,
                        });
                    }
                }
            }
            return Ok(Func::Call(name, args));
        }
        Ok(Func::Name(name))
    }
}

pub fn parse_prop(name: &str) -> Result<Prop, QError> {
    Ok(match name {
        "h" | "heading" => Prop::Heading,
        "h1" => Prop::H(1),
        "h2" => Prop::H(2),
        "h3" => Prop::H(3),
        "h4" => Prop::H(4),
        "h5" => Prop::H(5),
        "h6" => Prop::H(6),
        "code" => Prop::Code,
        "link" | "a" => Prop::Link,
        "img" | "image" => Prop::Img,
        "table" => Prop::Table,
        "list" => Prop::List,
        "blockquote" => Prop::Blockquote,
        _ => {
            return Err(QError {
                kind: ErrKind::UnknownProp(name.to_string()),
                line: String::new(),
                col: 0,
                span: 1,
            })
        }
    })
}

const FUNCS: [&str; 56] = [
    "count", "length", "len", "size", "first", "last", "head", "limit", "take", "skip", "drop",
    "nth", "reverse", "sort", "sort_by", "unique", "flatten", "group_by", "min", "max", "add",
    "text", "upper", "lower", "trim", "split", "join", "replace", "slugify", "lines", "words",
    "chars", "select", "where", "filter", "contains", "includes", "startswith", "endswith",
    "matches", "any", "all", "not", "content", "md", "url", "href", "src", "lang", "stats",
    "levels", "langs", "types", "matches", "flatten", "first", "last",
];

fn lev(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let n = a.len();
    let m = b.len();
    let mut prev: Vec<usize> = (0..=m).collect();
    let mut cur = vec![0usize; m + 1];
    for i in 1..=n {
        cur[0] = i;
        for j in 1..=m {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[m]
}

pub fn suggest(name: &str) -> Option<String> {
    let maxd = if name.chars().count() <= 2 { 3 } else { 2 };
    let mut cands: Vec<&str> = Vec::new();
    for f in FUNCS.iter() {
        let d = lev(name, f);
        if d <= maxd && !cands.contains(f) {
            cands.push(f);
        }
    }
    cands.truncate(3);
    if cands.is_empty() {
        None
    } else {
        Some(cands.join("' or '"))
    }
}
RSEOF
echo ok"}

