    let mut cands: Vec<&str> = Vec::new();
    for f in FUNCS.iter() {
        let d = lev(name, f);
        if d <= maxd && !cands.contains(f) {
            cands.push(f);
        }
    }
    cands.truncate(3);
    if cands.is_empty() {
