// ---- element model -------------------------------------------------------
#[derive(Clone, Debug)]
pub enum Elem {
    Heading {
        level: u8,
        text: String,
        offset: usize,
        line: usize,
        content: String,
        md: String,
    },
    Code {
        language: Option<String>,
        content: String,
    },
    Link {
        text: String,
        url: String,
        link_type: String,
        offset: usize,
    },
    Table {
        headers: Vec<String>,
        rows: Vec<Vec<String>>,
        alignments: Vec<String>,
    },
    List {
        ordered: bool,
        items: Vec<(String, Option<bool>)>,
    },
}

pub fn link_type_of(url: &str) -> &'static str {
    if url.starts_with("http://") || url.starts_with("https://") {
        "external"
    } else if url.starts_with('#') {
        "anchor"
    } else {
        "relative"
    }
}

/// Collect elements from document sections in document order
pub fn collect_elements(doc: &Document, raw: &str, sections: &[(usize, &Section, usize, usize, usize)]) -> Vec<Elem> {
    let _ = doc;
    let mut out: Vec<Elem> = Vec::new();
    for (sec_idx, s, _depth, _cstart, _cend) in sections {
        let _ = sec_idx;
        for b in &s.content.blocks {
            collect_block(b, &mut out, raw);
        }
    }
    out
}

fn collect_block(b: &Block, out: &mut Vec<Elem>, raw: &str) {
    let _ = raw;
    match b {
        Block::Code { language, content, .. } => {
            out.push(Elem::Code { language: language.clone(), content: content.clone() });
        }
        Block::Paragraph { inline, .. } => {
            for e in inline {
                if let Inline::Link { text, url, .. } = e {
                    out.push(Elem::Link {
                        text: text.clone(),
                        url: url.clone(),
                        link_type: link_type_of(url).to_string(),
                        offset: 0,
                    });
                }
            }
        }
        Block::List { items, .. } => {
            for it in items {
                for e in &it.inline {
                    if let Inline::Link { text, url, .. } = e {
                        out.push(Elem::Link {
                            text: text.clone(),
                            url: url.clone(),
                            link_type: link_type_of(url).to_string(),
                            offset: 0,
                        });
                    }
                }
            }
        }
        Block::Blockquote { blocks, .. } => {
            for b in blocks {
                collect_block(b, out, raw);
            }
        }
        Block::Table { headers, rows, alignments } => {
            out.push(Elem::Table { headers: headers.clone(), rows: rows.clone(), alignments: alignments.clone() });
        }
        _ => {}
    }
}

pub fn text_of(e: &Elem) -> String {
    match e {
        Elem::Heading { text, .. } => text.clone(),
