// Query evaluator
use crate::query::*;
use crate::qparse::*;
use crate::document::*;
use crate::markdown::*;

pub struct Ctx {
    pub doc: Document,
    pub flat: Vec<(usize, usize, Section)>, // sec_index_in_tree_unneeded; depth; section
    pub elems: Vec<Elem>,
    pub heading_secs: Vec<usize>, // elems index -> flat index
}

pub fn build_ctx(doc: Document, raw_text: &str, content_regions: Vec<(usize, usize, usize, usize, usize)>) -> Ctx {
    // flat sections in document order
    let mut flat: Vec<(usize, usize, Section)> = Vec::new();
    fn walk(s: &Section, d: usize, out: &mut Vec<(usize, usize, Section)>) {
        out.push((0, d, s.clone()));
        for c in &s.children {
            walk(c, d + 1, out);
        }
    }
    let sections = doc.sections.clone();
    for s in &sections {
        walk(s, 0, &mut flat);
    }
    // collect elements per section content region
    let mut elems: Vec<Elem> = Vec::new();
    let mut heading_secs: Vec<usize> = Vec::new();
    for (i, (_si, d, s)) in flat.iter().enumerate() {
        let _ = d;
        let region = content_regions.get(i);
        let blocks = match region {
            Some((_idx, cstart, _cl, _depth, _si2)) => {
                crate::blocks::parse_blocks(&raw_text[*cstart..content_regions[i].1.min(raw_text.len())], s.position.line)
            }
            None => s.content.blocks.clone(),
        };
        let _ = blocks;
    }
    // headings
    for (i, (_s, _d, s)) in flat.iter().enumerate() {
        let _ = i;
        elems.push(Elem::Heading {
            level: s.level,
            text: s.title.clone(),
            offset: s.position.offset,
            line: s.position.line,
            content: s.content.raw.clone(),
            md: String::new(),
        });
        heading_secs.push(elems.len() - 1);
    }
    let _ = &mut elems;
    // rebuild md for headings using content regions later
    Ctx { doc, flat, elems, heading_secs }
}
