// Build the Document (sections tree) from raw markdown text
use crate::markdown::*;
use crate::parse::*;
use crate::blocks::parse_blocks;

#[derive(Clone, Debug, Default)]
pub struct FlatSec {
    pub line: usize,          // 1-based heading text line
    pub offset: usize,        // byte offset of heading line start
    pub level: u8,
    pub title: String,
    pub raw: String,          // own content raw (trimmed)
    pub content_start: usize,
    pub content_end: usize,   // region used by query element collection
    pub md_start: usize,
    pub md_end: usize,        // md region (heading line .. next same-or-higher heading)
    pub blocks: Vec<Block>,
}

#[derive(Clone, Debug, Default)]
pub struct DocInfo {
    pub doc: Document,
    pub raw: String,
    pub flat: Vec<FlatSec>,
    pub children: Vec<Vec<usize>>,
    pub parent: Vec<Option<usize>>,
}

impl DocInfo {
    pub fn walk(&self) -> Vec<usize> {
        let mut out = Vec::new();
        fn go(info: &DocInfo, i: usize, out: &mut Vec<usize>) {
