    let li = f.line - 1;
    let l = lines.get(li);
    match l {
        Some(li2) => {
            let raw = &text[li2.start..li2.end_nl];
            let line = raw.trim_end_matches('\n');
            line.starts_with(' ') || line.starts_with('\t')
        }
