        let q_start = if let Some(l) = lines.get(line_idx + 1) { l.start } else { mend };
        let q_end = tight.iter().copied().find(|&b| b > q_start).unwrap_or(text.len());
        flat.push(FlatSec {
            line: line_idx + 1,
            offset: md_start,
            level,
            title: title.clone(),
            raw,
            content_start: cstart,
            content_end: cend,
            md_start,
            md_end,
            blocks: Vec::new(),
        });
        order.push(0);
    }
    // assign blocks using query region
    for i in 0..flat.len() {
        let pos_line = flat[i].line + 1 + if is_indented(text, &lines, flat[i]) { 1 } else { 0 };
        let region = text[flat[i].content_start.min(text.len())..flat[i].content_end.min(text.len())];
        let pos_line = flat_line_for_block(text, &lines, flat[i]);
        flat[i].blocks = parse_blocks(&region, pos_line);
    }
    // tree
    let n = flat.len();
    let mut children: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut parent: Vec<Option<usize>> = vec![None; n];
    let mut stack: Vec<usize> = Vec::new();
    for i in 0..n {
        while let Some(p) = stack.last().copied() {
            if flat[p].level >= flat[i].level {
                stack.pop();
            } else {
                break;
            }
        }
        if let Some(p) = stack.last().copied() {
            children[p].push(i);
            parent[i] = Some(p);
        }
        stack.push(i);
    }
    // sections (recursive)
    fn build_sec(info: &[(FlatSec)], children: &[Vec<usize>], i: usize) -> Section {
        let f = &info[i];
        Section {
            id: slugify(&f.title),
            level: f.level,
            title: f.title.clone(),
            slug: slugify(&f.title),
            position: Position { line: f.line + 1 + 0, offset: f.offset },
            content: Content { raw: f.raw.clone(), blocks: f.blocks.clone() },
            children: children[i].iter().map(|c| build_sec(info, children, *c)).collect(),
        }
    }
    let _ = pos_off;
    let pos_line_fix = |i: usize| {
        let f = &flat[i];
        let li = f.line - 1;
        let indented = is_indented(text, &lines, flat[i]);
        li + 2 + if indented { 1 } else { 0 }
    };
    for i in 0..n {
        let li = flat[i].line - 1;
        flat[i].line = pos_line_fix(i);
        let _ = li;
    }
    // positions stored: set proper line value now
    let mut sections: Vec<Section> = Vec::new();
    for i in 0..n {
        if parent[i].is_none() {
            sections.push(build_sec_with_pos(&flat, &children, i));
        }
    }
    let heading_count = sections.iter().map(|s| count_secs(s)).sum();
