        doc: Document {
            metadata: Metadata {
                source: source.map(|s| s.to_string()),
                heading_count,
                max_depth,
                word_count: count_words(text),
            },
            sections,
        },
        raw: text.to_string(),
        flat,
        children,
        parent,
    }
