fn inline_plain_len(s: &str) -> usize {
    crate::inline::parse_inline(s).iter().map(|i| i.plain().chars().count()).sum()
}

fn hlevel(h: &Head) -> u8 {
    match h {
        Head::Atx { level, .. } => *level,
        Head::Setext { level, .. } => *level,
    }
}

fn is_indented(text: &str, lines: &[LineInfo], f: &FlatSec) -> bool {
    let li = f.line - 1;
    let l = lines.get(li);
    match l {
        Some(li2) => {
            let raw = &text[li2.start..li2.end_nl];
            let line = raw.trim_end_matches('\n');
            line.starts_with(' ') || line.starts_with('\t')
        }
        None => false,
    }
}

fn flat_line_for_block(text: &str, lines: &[LineInfo], f: &FlatSec) -> usize {
    let li = f.line - 1;
    let indented = is_indented(text, lines, f);
    li + 2 + if indented { 1 } else { 0 }
}

fn build_sec_with_pos(flat: &[FlatSec], children: &[Vec<usize>], i: usize) -> Section {
    let f = &flat[i];
    Section {
        id: slugify(&f.title),
        level: f.level,
        title: f.title.clone(),
        slug: slugify(&f.title),
        position: Position { line: f.line, offset: f.offset },
        content: Content { raw: f.raw.clone(), blocks: f.blocks.clone() },
        children: children[i].iter().map(|c| build_sec_with_pos(flat, children, *c)).collect(),
    }
}

fn count_secs(s: &Section) -> usize {
    1 + s.children.iter().map(count_secs).sum::<usize>()
}

fn depth_of(i: usize, children: &[Vec<usize>]) -> usize {
    1 + children[i].iter().map(|c| depth_of(*c, children)).max().unwrap_or(0)
}
