    let tight: Vec<(usize, u8)> = headings
        .iter()
        .map(|h| match h {
            Head::Atx { line_idx, level, .. } => (lines[*line_idx].start, *level),
            Head::Setext { text_line, level, .. } => (lines[*text_line].start, *level),
        })
        .collect();

    let mut flat: Vec<FlatSec> = Vec::new();
    for h in &headings {
        let (line_idx, level, title, indented) = match h {
            Head::Atx { level, title, line_idx, indent, .. } => {
                (*line_idx, *level, title.clone(), *indent > 0)
            }
            Head::Setext { level, title, text_line } => {
                let l = &lines[*text_line];
                let raw_l = &text[l.start..l.end_nl];
                let t = raw_l.trim_end_matches('\n');
                let indent = t.len() - t.trim_start_matches([' ', '\t']).len();
                (*text_line, *level, title.clone(), indent > 0)
            }
        };
        let cs_line = line_idx + 1;
        let (has_nl, content_start) = match lines.get(cs_line) {
            Some(l) => (true, l.start),
            None => (false, text.len()),
        };
        let mstart = match h {
            Head::Atx { mstart, .. } => *mstart,
            Head::Setext { text_line, .. } => {
                let l = &lines[*text_line];
                l.start + text[l.start..l.end_nl].trim_end_matches('\n').len()
                    - text[l.start..l.end_nl].trim_end_matches('\n').trim_start_matches([' ', '\t']).len()
            }
        };
        let mend = match h {
            Head::Atx { mend, .. } => *mend,
            Head::Setext { text_line, .. } => lines[*text_line].start
                + text[lines[*text_line].start..lines[*text_line].end_nl].trim_end_matches('\n').len(),
        };
        let (pos_off, cstart) = if has_nl {
            (lines[cs_line].start, lines[cs_line].start)
        } else {
            let rest = &text[mend..];
            let ws = rest.starts_with(' ') || rest.starts_with('\t');
            (mstart, if ws { mend } else { mstart })
        };
        let cend = loose.iter().copied().find(|&b| b > cstart).unwrap_or(text.len());
        let raw = text[cstart.min(text.len())..cend].trim().to_string();
        let md_start = lines[line_idx].start;
        let md_end = tight
            .iter()
            .filter(|(off, lv)| *off > md_start && *lv <= level)
            .map(|(off, _)| *off)
            .next()
            .unwrap_or(text.len());
        let q_start = if let Some(l) = lines.get(line_idx + 1) { l.start } else { mend };
        let q_end = tight.iter().map(|(off, _)| *off).find(|&b| b > q_start).unwrap_or(text.len());
        let pos_line = line_idx + 2 + if indented { 1 } else { 0 };
        flat.push(FlatSec {
            line_idx,
            pos_line,
            pos_offset: pos_off,
            level,
            title: title.clone(),
            raw,
            content_start: cstart,
            content_end: cend,
            md_start,
            md_end,
            blocks: Vec::new(),
        });
        let _ = content_start;
    }
    for i in 0..flat.len() {
        let region = &text[flat[i].content_start.min(text.len())..flat[i].content_end.min(text.len())];
        flat[i].blocks = parse_blocks(region, flat[i].pos_line);
    }
    let n = flat.len();
    let mut children: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut parent: Vec<Option<usize>> = vec![None; n];
    let mut stack: Vec<usize> = Vec::new();
    for i in 0..n {
        while let Some(p) = stack.last().copied() {
            if flat[p].level >= flat[i].level {
                stack.pop();
            } else {
                break;
            }
        }
        if let Some(p) = stack.last().copied() {
            children[p].push(i);
            parent[i] = Some(p);
        }
        stack.push(i);
    }
    let mut sections: Vec<Section> = Vec::new();
    for i in 0..n {
        if parent[i].is_none() {
            sections.push(build_sec(&flat, &children, i));
        }
    }
    let heading_count = sections.iter().map(|s| count_secs(s)).sum();
    let max_depth = (0..n).map(|i| depth_of(i, &children)).max().unwrap_or(0);
    DocInfo {
        doc: Document {
            metadata: Metadata {
                source: source.map(|s| s.to_string()),
                heading_count,
                max_depth,
                word_count: count_words(text),
            },
            sections,
        },
        raw: text.to_string(),
        flat,
        children,
        parent,
    }
}

fn build_sec(flat: &[FlatSec], children: &[Vec<usize>], i: usize) -> Section {
    let f = &flat[i];
    Section {
        id: slugify(&f.title),
        level: f.level,
        title: f.title.clone(),
        slug: slugify(&f.title),
        position: Position { line: f.pos_line, offset: f.pos_offset },
        content: Content { raw: f.raw.clone(), blocks: f.blocks.clone() },
        children: children[i].iter().map(|c| build_sec(flat, children, *c)).collect(),
    }
}

fn count_secs(s: &Section) -> usize {
    1 + s.children.iter().map(count_secs).sum::<usize>()
}

fn depth_of(i: usize, children: &[Vec<usize>]) -> usize {
    1 + children[i].iter().map(|c| depth_of(*c, children)).max().unwrap_or(0)
}
