        crate::completion::setup_completions();
        return;
    }
    if let Some(sub) = matches.subcommand_matches("at-line") {
        let _l = sub.get_one::<String>("line");
        // effectively a no-op in this build
        return;
    }
    let files: Vec<String> = matches.get_many::<String>("file").map(|v| v.cloned().collect()).unwrap_or_default();
    let query = matches.get_one::<String>("query");
    let list = matches.get_flag("list");
    let tree = matches.get_flag("tree");
    let count = matches.get_flag("count");
    let section = matches.get_one::<String>("section");
    let output = matches.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("plain");
    let filter = matches.get_one::<String>("filter").map(|s| s.as_str());
    let level = matches.get_one::<String>("level").map(|s| s.as_str());
    let query_output = matches.get_one::<String>("query_output").map(|s| s.as_str()).unwrap_or("plain");

    // gather input
    let mut source: Option<String> = None;
    let mut text: Option<String> = None;
    let mut picker_mode = false;
    if files.iter().any(|f| f == "-") {
        let s = std::io::read_to_string(std::io::stdin()).unwrap_or_default();
        text = Some(s);
    } else if files.len() == 1 {
        let p = std::path::Path::new(&files[0]);
        if p.is_dir() {
            picker_mode = true;
        } else {
            match std::fs::read_to_string(p) {
                Ok(s) => {
                    source = Some(files[0].clone());
                    text = Some(s);
                }
                Err(e) => {
                    eprintln!("Error reading input: {}", crate::errors::io_message(&e));
                    std::process::exit(1);
                }
            }
        }
    } else if files.len() > 1 {
        let p = std::path::Path::new(&files[0]);
        match std::fs::read_to_string(p) {
            Ok(s) => {
                source = Some(files[0].clone());
                text = Some(s);
            }
            Err(e) => {
                eprintln!("Error reading input: {}", crate::errors::io_message(&e));
                std::process::exit(1);
            }
        }
    } else {
        // no file: stdin if piped else picker
        if !crate::errors::stdin_is_tty() {
            let s = std::io::read_to_string(std::io::stdin()).unwrap_or_default();
            text = Some(s);
        } else {
            picker_mode = true;
        }
    }

    let (info, label) = match text {
        Some(t) => {
            let info = crate::document::build(&t, source.as_deref(), 0);
            (info, source.clone().unwrap_or_else(|| "stdin".to_string()))
        }
        None => {
            let t = "# Select a file\n\nPress Enter to select a markdown file.\n";
            (crate::document::build(t, None, 0), "stdin".to_string())
        }
    };
    let _ = &label;

    if picker_mode {
        crate::tui::run_tui(&info, &label, &files, &matches);
        return;
    }

    if let Some(q) = query {
        crate::query::run_query(&info, q, query_output);
        return;
    }
    if count {
        print!("{}", crate::display::count_headings(&info.doc));
        return;
    }
    if let Some(name) = section {
        match crate::display::section_by_name(&info, name) {
            Some(s) => print!("{}", s),
            None => {
                eprintln!("Section '{}' not found", name);
                std::process::exit(1);
            }
        }
        return;
    }
    if tree {
        if output == "json" {
            print!("{}", crate::display::headings_json(&info));
        } else {
            print!("{}", crate::display::render_tree(&info.doc.sections, filter, level));
        }
        return;
    }
    if list {
        match output {
            "json" => print!("{}", crate::display::document_json(&info)),
            "tree" => println!("Use --tree for tree output"),
            _ => print!("{}", crate::display::list_headings(&info.doc, filter, level)),
        }
        return;
    }
    crate::tui::run_tui(&info, &label, &files, &matches);
}
