use std::io::Write;

pub fn prog_name() -> String {
    std::env::args_os()
        .next()
        .map(|a| std::path::PathBuf::from(a))
        .and_then(|p| p.file_name().map(|s| s.to_string_lossy().to_string()))
        .unwrap_or_else(|| "treemd".to_string())
}

fn shell_name() -> Option<String> {
    std::env::var("SHELL").ok().map(|s| {
        std::path::Path::new(&s)
            .file_name()
            .map(|f| f.to_string_lossy().to_string())
            .unwrap_or_else(|| s.clone())
    })
}

fn config_path(shell: &str) -> Option<std::path::PathBuf> {
    let home = std::env::var("HOME").ok()?;
    match shell {
        "bash" => Some(std::path::PathBuf::from(home).join(".bashrc")),
        "zsh" => Some(std::path::PathBuf::from(home).join(".zshrc")),
        "fish" => Some(std::path::PathBuf::from(home).join(".config/fish/config.fish")),
        _ => None,
    }
}

fn completion_line(shell: &str) -> Option<String> {
    let p = prog_name();
    match shell {
        "bash" => Some(format!("source <(COMPLETE=bash {})", p)),
        "zsh" => Some(format!("source <(COMPLETE=zsh {})", p)),
        "fish" => Some(format!("COMPLETE=fish {} | source", p)),
        _ => None,
    }
}

fn general_instructions() {
    let p = prog_name();
    println!("Shell Completion Setup Instructions");
    println!();
    println!("Add the appropriate line to your shell config:");
    println!();
    println!("Bash (~/.bashrc):");
    println!("  source <(COMPLETE=bash {})", p);
    println!();
    println!("Zsh (~/.zshrc):");
    println!("  source <(COMPLETE=zsh {})", p);
    println!();
    println!("Fish (~/.config/fish/config.fish):");
    println!("  COMPLETE=fish {} | source", p);
    println!();
    println!("After adding the line, restart your shell or source the config file.");
}

pub fn setup_completions() {
    let shell = match shell_name() {
        Some(s) => s,
        None => {
            general_instructions();
            eprintln!("Error setting up completions: Could not detect shell");
            std::process::exit(1);
        }
    };
    let line = match completion_line(&shell) {
        Some(l) => l,
        None => {
            general_instructions();
            eprintln!("Error setting up completions: Unsupported shell: {}", shell);
            std::process::exit(1);
        }
    };
    let path = match config_path(&shell) {
        Some(p) => p,
        None => {
            general_instructions();
            eprintln!("Error setting up completions: Unsupported shell: {}", shell);
            std::process::exit(1);
        }
    };
    println!("Detected shell: {}", shell);
    if let Ok(content) = std::fs::read_to_string(&path) {
        if content.contains(&line) {
            println!("✓ Shell completions are already set up in \"{}\"", path.display());
            return;
        }
    }
    println!();
    println!("To enable shell completions, add this line to \"{}\":", path.display());
    println!("  {}", line);
    println!();
    print!("Would you like to add it automatically? (y/N): ");
    let _ = std::io::stdout().flush();
    let mut answer = String::new();
    let _ = std::io::stdin().read_line(&mut answer);
    let answer = answer.trim().to_lowercase();
    if answer != "y" {
        println!();
        println!("Manually add the line above to enable completions.");
        return;
    }
    match std::fs::OpenOptions::new().append(true).create(true).open(&path) {
        Ok(mut f) => {
            let _ = writeln!(f);
            let _ = writeln!(f, "# {} shell completion", prog_name());
            let _ = writeln!(f, "{}", line);
            println!("✓ Added completions to \"{}\"", path.display());
            println!();
            println!("Restart your shell or run:");
            println!("  source \"{}\"", path.display());
        }
        Err(e) => {
            general_instructions();
            eprintln!("Error setting up completions: {}", e);
            std::process::exit(1);
        }
    }
}
