// CLI display functions
use crate::document::*;
use crate::markdown::*;

fn matches(s: &Section, filter: Option<&str>, level: Option<&str>) -> bool {
    if let Some(f) = filter {
        if !s.title.to_lowercase().contains(&f.to_lowercase()) {
            return false;
        }
    }
    if let Some(l) = level {
        if s.level.to_string() != l {
            return false;
        }
    }
    true
}

pub fn list_headings(doc: &Document, filter: Option<&str>, level: Option<&str>) -> String {
    let mut out = String::new();
    fn go(s: &Section, out: &mut String, filter: Option<&str>, level: Option<&str>) {
        if matches(s, filter, level) {
            out.push_str(&format!("{} {}\n", "#".repeat(s.level as usize), s.title));
        }
        for c in &s.children {
            go(c, out, filter, level);
        }
    }
    for s in &doc.sections {
        go(s, &mut out, filter, level);
    }
    out
}

pub fn render_tree(sections: &[Section], filter: Option<&str>, level: Option<&str>) -> String {
    let _ = filter;
    let _ = level;
    let mut out = String::new();
    for (i, s) in sections.iter().enumerate() {
        let last = i == sections.len() - 1;
        render_node(s, "", !last, &mut out);
    }
    out
}

fn render_node(s: &Section, prefix: &str, has_more_siblings: bool, out: &mut String) {
    let branch = if has_more_siblings { "├──" } else { "└──" };
    out.push_str(&format!(
        "{}{}{} {}\n",
        prefix,
        branch,
        "#".repeat(s.level as usize),
        s.title
    ));
    let n = s.children.len();
    for (i, c) in s.children.iter().enumerate() {
        let cont = if has_more_siblings { "│  " } else { "   " };
        render_node(c, &format!("{}{}", prefix, cont), i != n - 1, out);
    }
}

pub fn count_headings(doc: &Document) -> String {
    let mut counts = [0usize; 6];
    let mut total = 0usize;
    fn go(s: &Section, counts: &mut [usize; 6], total: &mut usize) {
        if s.level >= 1 && s.level <= 6 {
            counts[s.level as usize - 1] += 1;
            *total += 1;
        }
        for c in &s.children {
            go(c, counts, total);
        }
    }
    for s in &doc.sections {
        go(s, &mut counts, &mut total);
    }
    let mut out = String::from("Heading counts:\n");
    for i in 0..6 {
        if counts[i] > 0 {
            out.push_str(&format!("  {}: {}\n", "#".repeat(i + 1), counts[i]));
        }
    }
    out.push_str(&format!("\nTotal: {}\n", total));
    out
}

/// extract a section: heading line .. next heading of same or higher level
pub fn extract_section(info: &DocInfo, idx: usize) -> String {
    let f = &info.flat[idx];
    let slice = &info.raw[f.md_start..f.md_end.min(info.raw.len())];
    let trimmed = slice.trim();
    format!("{}\n", trimmed)
}

pub fn section_by_name(info: &DocInfo, name: &str) -> Option<String> {
    let target = name.to_lowercase();
    let flat = info.walk();
    for idx in &flat {
        if info.flat[*idx].title.to_lowercase() == target {
            return Some(extract_section(info, *idx));
        }
    }
    for idx in &flat {
        if info.flat[*idx].title == name {
            return Some(extract_section(info, *idx));
        }
    }
    for idx in &flat {
        if info.flat[*idx].title.to_lowercase().contains(&target) {
            return Some(extract_section(info, *idx));
        }
    }
    None
}

#[derive(serde::Serialize)]
struct Wrapper<'a> {
    document: &'a Document,
}

pub fn document_json(info: &DocInfo) -> String {
    serde_json::to_string_pretty(&Wrapper { document: &info.doc }).unwrap_or_default()
}

#[derive(serde::Serialize)]
struct HeadItem {
    level: u8,
    text: String,
}

pub fn headings_json(info: &DocInfo) -> String {
    let mut out = String::new();
    for idx in info.walk() {
        out.push_str(&format!(
            "{}  {{\n    \"level\": {},\n    \"text\": {}\n  }}",
            if out.is_empty() { "" } else { ",\n" },
            info.flat[idx].level,
            serde_json::to_string(&info.flat[idx].title).unwrap_or_default()
        ));
    }
    format!("[\n{}]\n\n", out)
}
