// Query evaluator
use crate::query::*;
use crate::qparse::*;
use crate::document::DocInfo;
use crate::markdown::*;

#[derive(Clone, Debug)]
pub enum Elem {
    Heading { fidx: usize, level: u8, text: String, offset: usize, line: usize, content: String, md: String },
    Code { language: Option<String>, content: String },
    Link { text: String, url: String, link_type: String, offset: usize },
    Table { headers: Vec<String>, rows: Vec<Vec<String>>, alignments: Vec<String> },
    List { ordered: bool, items: Vec<(String, Option<bool>)> },
}

#[derive(Clone, Debug)]
pub enum Val {
    Elem(usize),
    Str(String),
    Num(f64),
    Bool(bool),
    Arr(Vec<Val>),
    Obj(Vec<(String, Val)>),
    Doc,
    Null,
}

pub struct Ctx<'a> {
    pub info: &'a DocInfo,
    pub elems: Vec<Elem>,
    pub heading_fidx: Vec<usize>,
}

fn link_type_of(url: &str) -> &'static str {
    if url.starts_with("http://") || url.starts_with("https://") {
        "external"
    } else if url.starts_with('#') {
        "anchor"
    } else {
        "relative"
    }
}

fn build_elems(info: &DocInfo) -> (Vec<Elem>, Vec<usize>) {
