}

/// plain rendering used by default output
pub fn plain_of(e: &Elem) -> String {
    match e {
        Elem::Heading { level, text, .. } => format!("{} {}", "#".repeat(*level as usize), text),
        Elem::Code { language, content, .. } => match language {
            Some(l) => format!("```{}\n{}\n```", l, content),
            None => format!("```\n{}\n```", content),
        },
        Elem::Link { text, url, .. } => format!("[{}]({})", text, url),
        Elem::Table { headers, rows, .. } => render_box_table(headers, rows),
        Elem::List { ordered, items } => {
            let mut s = String::new();
            for (i, it) in items.iter().enumerate() {
                let prefix = if *ordered {
                    format!("{}. ", i + 1)
                } else {
                    "- ".to_string()
                };
                let cb = match it.1 {
                    Some(false) => "[ ] ",
                    Some(true) => "[x] ",
                    None => "",
                };
                s.push_str(&format!("{}{}{}", prefix, cb, it.0));
                s.push('\n');
            }
            s
        }
    }
}

pub fn render_box_table(headers: &[String], rows: &[Vec<String>]) -> String {
    let widths: Vec<usize> = headers
        .iter()
        .enumerate()
        .map(|(i, h)| {
            let mut m = h.chars().count();
            for r in rows {
                if let Some(c) = r.get(i) {
                    m = m.max(c.chars().count());
                }
            }
            m
        })
        .collect();
    let mut s = String::new();
    let line = |l: &str, m: &str, r: &str| -> String {
        let mut t = String::from(l);
        for (i, w) in widths.iter().enumerate() {
            if i > 0 {
                t.push_str(m);
            }
            t.push_str(&"─".repeat(w + 2));
        }
        t.push_str(r);
        t
    };
    s.push_str(&line("┌", "┬", "┐"));
    s.push('\n');
    for (i, h) in headers.iter().enumerate() {
        s.push_str(&format!("│ {}{}", h, " ".repeat(widths[i] - h.chars().count())));
        if i == headers.len() - 1 {
            s.push(' ');
        }
    }
    s.push_str("│\n");
    s.push_str(&line("├", "┼", "┤"));
    s.push('\n');
    for r in rows {
        for (i, c) in r.iter().enumerate() {
            s.push_str(&format!("│ {}{}", c, " ".repeat(widths[i] - c.chars().count())));
            if i == widths.len() - 1 {
                s.push(' ');
            }
        }
        s.push_str("│\n");
    }
    s.push_str(&line("└", "┴", "┘"));
    s.push('\n');
    s
}

fn truthy(v: &Val) -> bool {
    match v {
        Val::Bool(b) => *b,
        Val::Str(s) => !s.is_empty() && s != "false",
        Val::Num(n) => *n != 0.0,
        Val::Arr(a) => !a.is_empty(),
        Val::Null => false,
        _ => true,
    }
}
