fn kind_matches(e: &Elem, p: &Prop) -> bool {
    match (e, p) {
        (Elem::Heading { level, .. }, Prop::Heading) => true,
        (Elem::Heading { level, .. }, Prop::H(n)) => level == n,
        (Elem::Code { .. }, Prop::Code) => true,
        (Elem::Link { .. }, Prop::Link) => true,
        (Elem::Table { .. }, Prop::Table) => true,
        (Elem::List { .. }, Prop::List) => true,
        _ => false,
    }
}

fn filter_text(e: &Elem) -> String {
    match e {
        Elem::Heading { text, .. } => text.clone(),
        Elem::Code { content, .. } => content.clone(),
        Elem::Link { text, .. } => text.clone(),
        Elem::Table { .. } => String::new(),
        Elem::List { .. } => String::new(),
    }
}

fn apply_filter(list: Vec<usize>, ctx: &Ctx, f: &Filter) -> Vec<usize> {
    match f {
        Filter::None => list,
        Filter::Index(n) => {
            let len = list.len();
            let idx = if *n < 0 { len as i64 + *n } else { *n };
            if idx >= 0 && (idx as usize) < len {
                vec![list[idx as usize]]
            } else {
                vec![]
            }
        }
        Filter::Range(a, b) => {
            let len = list.len() as i64;
            let s = match a {
                Some(v) => {
                    if *v < 0 {
                        (len + *v).max(0) as usize
                    } else {
                        (*v).min(len) as usize
                    }
                }
                None => 0,
            };
            let e = match b {
                Some(v) => {
                    if *v < 0 {
                        (len + *v).max(s as i64) as usize
                    } else {
                        (*v).min(len) as usize
                    }
                }
                None => len as usize,
            };
            if s <= e && e <= list.len() {
                list[s..e].to_vec()
            } else {
                vec![]
            }
        }
        Filter::LinkKind(k) => list
            .into_iter()
            .filter(|i| matches!(&ctx.elems[*i], Elem::Link { link_type, .. } if link_type == k))
            .collect(),
        Filter::Exact(t) => list
            .into_iter()
            .filter(|i| filter_text(&ctx.elems[*i]) == *t)
            .collect(),
        Filter::Fuzzy(t) => list
            .into_iter()
            .filter(|i| filter_text(&ctx.elems[*i]).to_lowercase().contains(&t.to_lowercase()))
            .collect(),
    }
}

pub fn eval(ast: &Ast, ctx: &Ctx) -> Result<Vec<Val>, QError> {
    match ast {
        Ast::Select(prop, filter) => {
            let mut list: Vec<usize> = Vec::new();
            for (i, e) in ctx.elems.iter().enumerate() {
                if kind_matches(e, prop) {
                    list.push(i);
                }
            }
            Ok(apply_filter(list, ctx, filter).into_iter().map(Val::Elem).collect())
        }
        Ast::Doc => Ok(vec![Val::Doc]),
        Ast::Collect(inner) => Ok(vec![Val::Arr(eval(inner, ctx)?)]),
        Ast::Pipe(inner, func) => {
            let vals = eval(inner, ctx)?;
            Ok(apply_func(&vals, func, ctx)?)
        }
        Ast::Hierarchy(left, desc, right) => {
            let lvals = eval(left, ctx)?;
            let mut out = Vec::new();
            for v in lvals {
                let fidx = match &v {
                    Val::Elem(i) => match &ctx.elems[*i] {
                        Elem::Heading { fidx, .. } => Some(*fidx),
                        _ => None,
                    },
                    _ => None,
                };
                match (&*right, fidx) {
                    (Ast::Select(rp, rf), Some(f)) if is_head_prop(rp) => {
                        let mut list: Vec<usize> = Vec::new();
                        collect_headings(ctx, f, *desc, rp, &mut list);
                        for i in apply_filter(list, ctx, rf) {
                            out.push(Val::Elem(i));
                        }
                    }
                    _ => {
                        out.extend(eval(right, ctx)?);
                    }
                }
            }
            Ok(out)
        }
        Ast::Func(_) => Ok(vec![]),
    }
}

fn is_head_prop(p: &Prop) -> bool {
    matches!(p, Prop::Heading | Prop::H(_))
}

fn collect_headings(ctx: &Ctx, fidx: usize, desc: bool, prop: &Prop, out: &mut Vec<usize>) {
    let f = &ctx.info.flat[fidx];
    let level = f.level;
    let direct = &ctx.info.children[fidx];
    if desc {
        fn go(ctx: &Ctx, i: usize, prop: &Prop, out: &mut Vec<usize>) {
            if let Some(ei) = ctx.heading_fidx.get(i) {
                if kind_matches(&ctx.elems[*ei], prop) {
                    out.push(*ei);
                }
            }
            for c in &ctx.info.children[i] {
                go(ctx, *c, prop, out);
            }
        }
        for c in direct {
            go(ctx, *c, prop, out);
        }
    } else {
        for c in direct {
            if let Some(ei) = ctx.heading_fidx.get(*c) {
                if kind_matches(&ctx.elems[*ei], prop) {
                    out.push(*ei);
                }
            }
        }
    }
    let _ = level;
}

fn arr_text(v: &Val) -> String {
    match v {
        Val::Str(s) => s.clone(),
        Val::Arr(a) => a.iter().map(arr_text).collect::<Vec<_>>().join("\n"),
        Val::Num(n) => fmt_num(*n),
        Val::Bool(b) => b.to_string(),
        Val::Elem(i) => {
            let _ = i;
            String::new()
        }
        _ => String::new(),
    }
}

fn fmt_num(n: f64) -> String {
    if n.fract() == 0.0 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

pub fn apply_func(vals: &[Val], f: &Func, ctx: &Ctx) -> Result<Vec<Val>, QError> {
    let (name, args): (&str, Vec<String>) = match f {
        Func::Name(n) => (n.as_str(), vec![]),
        Func::Call(n, a) => (n.as_str(), a.clone()),
    };
    let n_args = args.len();
    let need = |lo: usize, hi: usize| -> Result<(), QError> {
        if n_args < lo || n_args > hi {
            Err(QError {
                kind: ErrKind::Other(format!("Function '{}' expects {}..={} arguments, got {}", name, lo, hi, n_args)),
                line: String::new(),
                col: 0,
                span: 1,
            })
        } else {
            Ok(())
        }
    };
    match name {
        "stats" | "levels" | "langs" | "types" => Ok(vec![doc_func(name, ctx)]),
        _ => {}
    }
    match name {
        "count" | "length" | "len" | "size" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => out.push(Val::Num(a.len() as f64)),
                    Val::Str(s) => out.push(Val::Num(s.chars().count() as f64)),
                    _ => out.push(Val::Num(1.0)),
                }
            }
            Ok(out)
        }
        "first" | "head" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => out.push(a.first().cloned().unwrap_or(Val::Null)),
                    _ => out.push(v.clone()),
                }
            }
            Ok(out)
        }
        "last" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => out.push(a.last().cloned().unwrap_or(Val::Null)),
                    _ => out.push(v.clone()),
                }
            }
            Ok(out)
        }
        "limit" | "take" => {
            need(1, 1)?;
            let n: usize = args[0].parse().unwrap_or(0);
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => out.push(Val::Arr(a.iter().take(n).cloned().collect())),
                    _ => out.push(v.clone()),
                }
            }
            Ok(out)
        }
        "skip" | "drop" => {
            need(1, 1)?;
            let n: usize = args[0].parse().unwrap_or(0);
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => out.push(Val::Arr(a.iter().skip(n).cloned().collect())),
