                match v {
                    Val::Arr(a) => out.push(a.last().cloned().unwrap_or(Val::Null)),
                    _ => out.push(v.clone()),
                }
            }
            Ok(out)
        }
        "limit" | "take" => {
            need(1, 1)?;
            let n: usize = args[0].parse().unwrap_or(0);
