        }
        "url" | "href" | "src" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Elem(i) => match &ctx.elems[*i] {
                        Elem::Link { url, .. } => out.push(Val::Str(url.clone())),
                        _ => out.push(Val::Str(String::new())),
                    },
                    _ => out.push(Val::Str(String::new())),
                }
            }
            Ok(out)
        }
        "lang" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Elem(i) => match &ctx.elems[*i] {
                        Elem::Code { language, .. } => out.push(Val::Str(language.clone().unwrap_or_default())),
                        _ => out.push(Val::Str(String::new())),
                    },
                    _ => out.push(Val::Str(String::new())),
                }
            }
            Ok(out)
        }
        "content" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Elem(i) => match &ctx.elems[*i] {
                        Elem::Heading { content, .. } => out.push(Val::Str(content.clone())),
                        other => out.push(Val::Str(text_of(other))),
                    },
                    Val::Str(s) => out.push(Val::Str(s.clone())),
                    _ => out.push(Val::Str(String::new())),
                }
            }
            Ok(out)
        }
        "upper" | "lower" | "trim" | "slugify" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => {
                        let mut b = Vec::new();
                        for x in a {
                            let s = val_text(ctx, &x);
                            b.push(Val::Str(match name {
                                "upper" => s.to_uppercase(),
                                "lower" => s.to_lowercase(),
                                "trim" => s.trim().to_string(),
                                _ => crate::markdown::slugify(&s),
                            }));
                        }
                        out.push(Val::Arr(b));
                    }
                    _ => {
                        let s = val_text(ctx, v);
                        out.push(Val::Str(match name {
                            "upper" => s.to_uppercase(),
                            "lower" => s.to_lowercase(),
                            "trim" => s.trim().to_string(),
                            _ => crate::markdown::slugify(&s),
                        }));
                    }
                }
            }
            Ok(out)
        }
        "split" => {
            need(1, 1)?;
            let sep = &args[0];
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => out.push(Val::Arr(a)),
                    _ => {
                        let s = val_text(ctx, v);
                        out.push(Val::Arr(s.split(sep.as_str()).map(|p| Val::Str(p.to_string())).collect()));
                    }
                }
            }
            Ok(out)
        }
        "join" => {
            need(1, 1)?;
            let sep = &args[0];
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => {
                        let parts: Vec<String> = a.iter().map(|x| val_text(ctx, x)).collect();
                        out.push(Val::Str(parts.join(sep)));
                    }
                    _ => out.push(v.clone()),
                }
            }
            Ok(out)
        }
        "replace" => {
            need(2, 2)?;
            let mut out = Vec::new();
            for v in vals {
                let s = val_text(ctx, v);
                out.push(Val::Str(s.replace(&args[0], &args[1])));
            }
            Ok(out)
        }
        "lines" | "words" | "chars" => {
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => {
                        let mut c = 0usize;
                        for x in a {
                            let s = val_text(ctx, &x);
                            c += match name {
                                "lines" => s.split('\n').count(),
                                "words" => s.split_whitespace().count(),
                                _ => s.chars().count(),
                            };
                        }
                        out.push(Val::Num(c as f64));
                    }
                    _ => {
                        let s = val_text(ctx, v);
                        out.push(Val::Num(match name {
                            "lines" => s.split('\n').count(),
                            "words" => s.split_whitespace().count(),
                            _ => s.chars().count(),
                        } as f64));
                    }
                }
            }
            Ok(out)
        }
        "select" | "where" | "filter" => {
            need(1, 1)?;
            let cond = args[0].clone();
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => out.push(Val::Arr(a)),
                    _ => {
                        let keep = eval_cond(ctx, v, &cond, name);
                        if keep {
                            out.push(v.clone());
                        }
                    }
                }
            }
            Ok(out)
        }
        "contains" | "includes" => {
            need(1, 1)?;
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => {
                        let all = a.iter().map(|x| val_text(ctx, x)).collect::<String>();
                        out.push(Val::Bool(all.contains(&args[0])));
                    }
                    _ => {
                        let s = val_text(ctx, v);
                        out.push(Val::Bool(s.contains(&args[0])));
                    }
                }
            }
            Ok(out)
        }
        "startswith" | "endswith" => {
            need(1, 1)?;
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => {
                        let all = a.iter().map(|x| val_text(ctx, x)).collect::<String>();
                        out.push(Val::Bool(if name == "startswith" { all.starts_with(&args[0]) } else { all.ends_with(&args[0]) }));
                    }
                    _ => {
                        let s = val_text(ctx, v);
                        out.push(Val::Bool(if name == "startswith" { s.starts_with(&args[0]) } else { s.ends_with(&args[0]) }));
                    }
                }
            }
            Ok(out)
        }
        "matches" => {
            need(1, 1)?;
            let mut out = Vec::new();
            for v in vals {
                out.push(Val::Bool(false));
            }
            Ok(out)
        }
        "any" | "all" => {
            need(1, 1)?;
            let _ = args[0].clone();
            let mut out = Vec::new();
            for v in vals {
                match v {
                    Val::Arr(a) => {
                        let r = if name == "any" { a.iter().any(truthy) } else { a.iter().all(truthy) };
                        out.push(Val::Bool(r));
                    }
                    _ => out.push(Val::Bool(truthy(v))),
                }
            }
            Ok(out)
        }
        "not" => {
            let mut out = Vec::new();
            for v in vals {
                out.push(Val::Bool(!truthy(v)));
            }
            Ok(out)
        }
        _ => {
            return Err(QError {
                kind: ErrKind::UnknownFunc(name.to_string(), crate::qparse::suggest(name)),
                line: String::new(),
                col: 0,
                span: 1,
            })
        }
    }
}

fn eval_cond(ctx: &Ctx, v: &Val, cond: &str, fname: &str) -> bool {
    // cond is the textual argument of select/where/filter; only contains() supported
    if let Some(inner) = cond.strip_prefix("contains(") {
        let arg = inner.trim_end_matches(')').trim().trim_matches('"').trim_matches('\'');
        let s = val_text(ctx, v);
        return match fname {
            "select" => s.contains(arg),
            _ => s.to_lowercase().contains(&arg.to_lowercase()),
        };
    }
    if let Some(inner) = cond.strip_prefix("includes(") {
        let arg = inner.trim_end_matches(')').trim().trim_matches('"').trim_matches('\'');
        let s = val_text(ctx, v);
        return s.contains(arg);
    }
    false
}

fn val_text(ctx: &Ctx, v: &Val) -> String {
    match v {
        Val::Str(s) => s.clone(),
        Val::Num(n) => fmt_num(*n),
        Val::Bool(b) => b.to_string(),
        Val::Elem(i) => {
            let e = &ctx.elems[*i];
            match e {
                Elem::Heading { text, .. } => text.clone(),
                _ => text_of(e),
            }
        }
        Val::Arr(a) => a.iter().map(|x| val_text(ctx, x)).collect::<Vec<_>>().join("\n"),
        Val::Obj(_) => String::new(),
        Val::Doc => ctx.info.raw.clone(),
        Val::Null => String::new(),
    }
}

fn val_md(ctx: &Ctx, v: &Val) -> String {
    match v {
        Val::Str(s) => s.clone(),
        Val::Elem(i) => md_of(&ctx.elems[*i], ctx.info),
        Val::Arr(a) => a.iter().map(|x| val_md(ctx, x)).collect::<Vec<_>>().join("\n"),
        Val::Doc => ctx.info.raw.clone(),
        _ => String::new(),
    }
}

fn sort_key(v: &Val) -> String {
    match v {
        Val::Str(s) => s.clone(),
        Val::Num(n) => fmt_num(*n),
        Val::Bool(b) => b.to_string(),
        _ => String::new(),
    }
}

fn val_key(v: &Val, ctx: &Ctx) -> String {
    match v {
        Val::Elem(i) => val_text(ctx, v),
        _ => sort_key(v),
    }
}

fn group_key(ctx: &Ctx, v: &Val, key: &str) -> String {
    match v {
        Val::Elem(i) => {
            let e = &ctx.elems[*i];
            match e {
                Elem::Heading { level, text, offset, line, content, .. } => match key {
                    "level" => format!("h{}", level),
                    "text" => text.clone(),
                    "line" => format!("{}", line),
                    "offset" => format!("{}", offset),
                    "content" => content.clone(),
                    _ => text.clone(),
                },
                Elem::Link { text, url, link_type, offset } => match key {
                    "link_type" | "type" => link_type.clone(),
                    "text" => text.clone(),
                    "url" => url.clone(),
                    "offset" => format!("{}", offset),
                    _ => text.clone(),
                },
                Elem::Code { language, .. } => match key {
                    "language" | "lang" => language.clone().unwrap_or_default(),
                    _ => String::new(),
                },
                Elem::Table { .. } => text_of(e),
                Elem::List { items, .. } => {
                    let _ = key;
                    items.iter().map(|it| it.0.clone()).collect::<String>()
                }
            }
        }
        _ => val_text(ctx, v),
    }
}

fn prop_of(ctx: &Ctx, i: usize, key: &str) -> String {
    let e = &ctx.elems[i];
    match e {
        Elem::Heading { level, text, line, offset, .. } => match key {
            "level" => format!("{:0>2}", level),
            "line" => format!("{}", line),
            "offset" => format!("{}", offset),
            _ => text.clone(),
        },
        _ => val_text(ctx, &Val::Elem(i)),
    }
}

fn doc_func(name: &str, ctx: &Ctx) -> Val {
    match name {
        "stats" => {
            let mut headings = 0usize;
            let mut code_blocks = 0usize;
            let mut links = 0usize;
            let mut images = 0usize;
            let mut tables = 0usize;
            let mut lists = 0usize;
            for e in &ctx.elems {
                match e {
                    Elem::Heading { .. } => headings += 1,
                    Elem::Code { .. } => code_blocks += 1,
                    Elem::Link { .. } => links += 1,
                    Elem::Table { .. } => tables += 1,
                    Elem::List { .. } => lists += 1,
                }
            }
            let _ = images;
            Val::Str(format!(
                "headings: {}\ncode_blocks: {}\nlinks: {}\nimages: {}\ntables: {}\nlists: {}\nwords: {}",
                headings,
                code_blocks,
                links,
                images,
                tables,
                lists,
                crate::markdown::count_words(&ctx.info.raw)
            ))
        }
        "levels" => {
            let mut counts = [0usize; 6];
            for i in ctx.walk_secs() {
                let f = &ctx.info.flat[i];
                if f.level >= 1 && f.level <= 6 {
                    counts[f.level as usize - 1] += 1;
                }
            }
            let mut s = String::new();
            for i in 0..6 {
                if counts[i] > 0 {
                    s.push_str(&format!("h{}: {}\n", i + 1, counts[i]));
                }
            }
            Val::Str(s)
        }
        "langs" => {
            let mut groups: Vec<(String, usize)> = Vec::new();
            for e in &ctx.elems {
                if let Elem::Code { language, .. } = e {
                    let l = language.clone().unwrap_or_default();
                    match groups.iter_mut().find(|(g, _)| *g == l) {
                        Some((_, c)) => *c += 1,
                        None => groups.push((l, 1)),
                    }
                }
            }
            let mut s = String::new();
            for (l, c) in groups {
                s.push_str(&format!("{}: {}\n", l, c));
            }
            Val::Str(s)
        }
        "types" => {
            let mut groups: Vec<(String, usize)> = Vec::new();
            for e in &ctx.elems {
                if let Elem::Link { link_type, .. } = e {
                    match groups.iter_mut().find(|(g, _)| *g == *link_type) {
                        Some((_, c)) => *c += 1,
                        None => groups.push((link_type.clone(), 1)),
                    }
                }
            }
            let mut s = String::new();
            for (l, c) in groups {
                s.push_str(&format!("{}: {}\n", l, c));
            }
            Val::Str(s)
        }
        _ => Val::Null,
    }
}

impl<'a> Ctx<'a> {
    fn walk_secs(&self) -> Vec<usize> {
        self.info.walk()
    }
}
