fn tree_render(v: &Val, ctx: &Ctx, out: &mut String, prefix: &str, last: bool) {
    let branch = if last { "└──" } else { "├──" };
    match v {
        Val::Arr(a) => {
            out.push_str(&format!("{}{}[\n", prefix, branch));
            let n = a.len();
            for (i, x) in a.iter().enumerate() {
                tree_render(x, ctx, out, &format!("{}   ", prefix), i == n - 1);
            }
            out.push_str(&format!("{}   ]\n", prefix));
        }
        Val::Obj(o) => {
            out.push_str(&format!("{}{}{{\n", prefix, branch));
            let n = o.len();
            for (i, (k, x)) in o.iter().enumerate() {
                out.push_str(&format!("{}   {}{}: ", prefix, if i == n - 1 { "└──" } else { "├──" }, k));
                tree_render(x, ctx, out, "", true);
            }
            out.push_str(&format!("{}   }}\n", prefix));
        }
        Val::Elem(i) => {
            out.push_str(&format!("{}{}{}\n", prefix, branch, plain_of(&ctx.elems[*i])));
        }
        _ => {
            out.push_str(&format!("{}{}{}\n", prefix, branch, val_text(ctx, v)));
        }
    }
}

pub fn run_query(info: &crate::document::DocInfo, expr: &str, output: &str) {
    let ast = match parse_query(expr) {
        Ok(a) => a,
        Err(e) => {
            eprint!("{}", e.message());
            std::process::exit(1);
        }
    };
    let ctx = Ctx::new(info);
    let vals = match eval(&ast, &ctx) {
        Ok(v) => v,
        Err(e) => {
            eprint!("{}", e.message());
            std::process::exit(1);
        }
    };
    let fmt = match output {
        "plain" => "plain",
        "json" => "json",
        "json-pretty" => "json-pretty",
        "jsonp" => "jsonp",
        "jsonl" => "jsonl",
        "md" => "md",
        "tree" => "tree",
        other => {
            eprint!("Error: Unknown output format: {}\n", other);
            std::process::exit(1);
        }
    };
    match fmt {
        "jsonp" => {
            eprint!("Error: Unknown output format: jsonp\n");
            std::process::exit(1);
        }
        "plain" => {
            let mut out = String::new();
            for v in &vals {
                out.push_str(&plain_value(&ctx, v));
            }
            if !out.is_empty() {
                print!("{}\n", out);
            }
        }
        "md" => {
            let mut out = String::new();
            for v in &vals {
                out.push_str(&val_md(&ctx, v));
            }
            if !out.is_empty() {
                print!("{}\n", out);
            }
        }
        "json" => println!("{}", serde_json::to_string(&serde_json::Value::Array(vals.iter().map(|v| value_json(&ctx, v)).collect())).unwrap_or_default()),
        "json-pretty" => println!("{}", serde_json::to_string_pretty(&serde_json::Value::Array(vals.iter().map(|v| value_json(&ctx, v)).collect())).unwrap_or_default()),
        "jsonl" => {
            for v in &vals {
                println!("{}", serde_json::to_string(&value_json(&ctx, v)).unwrap_or_default());
            }
        }
        "tree" => {
            let mut out = String::new();
            for (i, v) in vals.iter().enumerate() {
                tree_render(v, &ctx, &mut out, "", i == vals.len() - 1);
            }
            print!("{}\n", out);
        }
        _ => {}
    }
}

fn plain_value(ctx: &Ctx, v: &Val) -> String {
    match v {
        Val::Elem(i) => plain_of(&ctx.elems[*i]),
        Val::Str(s) => s.clone(),
        Val::Num(n) => fmt_num(*n),
        Val::Bool(b) => b.to_string(),
        Val::Arr(a) => a.iter().map(|x| plain_value(ctx, x)).collect::<Vec<_>>().join("\n"),
        Val::Obj(o) => serde_json::to_string(&{
            let mut m = serde_json::Map::new();
            for (k, vv) in o {
                let jv = match vv {
                    Val::Arr(inner) => serde_json::Value::Array(
                        inner.iter().map(|x| match x { Val::Elem(i) => elem_json_full(ctx, *i), other => value_json(ctx, other) }).collect(),
                    ),
                    other => value_json(ctx, other),
                };
                m.insert(k.clone(), jv);
            }
            serde_json::Value::Object(m)
        })
        .unwrap_or_default(),
        Val::Doc => ctx.info.raw.clone(),
        Val::Null => String::new(),
    }
}
