// Inline element parsing
use crate::markdown::*;

#[derive(Clone, Copy, PartialEq)]
pub enum Kind {
    Text,
    Strike,
    Emphasis,
    Strong,
}

impl Kind {
    fn rank(&self) -> u8 {
        match self {
            Kind::Text => 0,
            Kind::Strike => 1,
            Kind::Emphasis => 2,
            Kind::Strong => 3,
        }
    }
    fn to_type(&self, value: String) -> Inline {
        match self {
            Kind::Text => Inline::Text { value },
            Kind::Strike => Inline::Strikethrough { value },
            Kind::Emphasis => Inline::Emphasis { value },
            Kind::Strong => Inline::Strong { value },
        }
    }
}

fn run_of(chars: &[char], i: usize, c: char) -> usize {
    let mut r = 0;
    while i + r < chars.len() && chars[i + r] == c {
        r += 1;
    }
    r
}

/// find closing run of `c` with length >= run; returns (end_index_after_close, inner_start, inner_end)
fn find_closer(chars: &[char], from: usize, c: char, run: usize) -> Option<(usize, usize, usize)> {
    let n = chars.len();
    let mut j = from;
    while j < n {
        if chars[j] == c {
            let m = run_of(chars, j, c);
            if m >= run {
                let close_start = j + m - run;
                let inner_end = close_start;
                let end = j + m;
                if inner_end > from {
                    return Some((end, from, inner_end));
                }
                return None;
            }
            j += m;
        } else {
            j += 1;
        }
    }
    None
}

fn scan_code(chars: &[char], start: usize) -> Option<(usize, String)> {
    let n = chars.len();
    let mut j = start + 1;
    while j < n {
        if chars[j] == '`' {
            let v: String = chars[start + 1..j].iter().collect();
            return Some((j + 1, v));
        }
        j += 1;
    }
    None
}

fn scan_link(chars: &[char], start: usize) -> Option<(usize, String, String)> {
    let n = chars.len();
    let mut j = start + 1;
    let mut text_end = None;
    while j < n {
        if chars[j] == ']' {
            text_end = Some(j);
            break;
        }
        j += 1;
    }
    let te = text_end?;
