        if chars[j] == '`' {
            let v: String = chars[start + 1..j].iter().collect();
            return Some((j + 1, v));
        }
        j += 1;
    }
    None
}

fn scan_link(chars: &[char], start: usize) -> Option<(usize, String, String)> {
    let n = chars.len();
    let mut j = start + 1;
    let mut text_end = None;
    while j < n {
        if chars[j] == ']' {
            text_end = Some(j);
            break;
        }
        j += 1;
    }
    let te = text_end?;
    if te + 1 < n && chars[te + 1] == '(' {
        let mut k = te + 2;
        while k < n && chars[k] != ')' {
            k += 1;
        }
        if k < n {
            let text: String = chars[start + 1..te].iter().collect();
            let url: String = chars[te + 2..k].iter().collect();
            return Some((k + 1, text, url));
        }
    }
    None
}

fn scan_image(chars: &[char], start: usize) -> Option<(usize, String, String)> {
    let (end, text, url) = scan_link(chars, start + 1)?;
    Some((end, text, url))
}

fn scan_html_tag(chars: &[char], start: usize) -> Option<usize> {
    let n = chars.len();
    let mut j = start + 1;
    while j < n {
        if chars[j] == '>' {
            return Some(j + 1);
        }
        if chars[j] == '<' {
            return None;
        }
        j += 1;
    }
    None
}

fn scan_entity(chars: &[char], start: usize) -> Option<(usize, String)> {
    let n = chars.len();
    let mut j = start + 1;
    let mut digits = false;
    let mut alpha = false;
    let mut alpha_str = String::new();
    while j < n {
        let c = chars[j];
        if c == ';' {
            if digits && !alpha && j > start + 1 && chars[start + 1] == '#' {
                let num: String = chars[start + 2..j].iter().collect();
                if let Ok(v) = num.parse::<u32>() {
                    if let Some(ch) = char::from_u32(v) {
                        return Some((j + 1, ch.to_string()));
                    }
                }
                return None;
            }
            if alpha {
                let name = alpha_str.to_lowercase();
                let rep = match name.as_str() {
                    "amp" => "&",
                    "lt" => "<",
                    "gt" => ">",
                    "quot" => "\"",
                    "apos" => "'",
                    "nbsp" => "\u{a0}",
                    "copy" => "\u{a9}",
                    "hellip" => "\u{2026}",
                    "mdash" => "\u{2014}",
                    "ndash" => "\u{2013}",
                    "larr" => "\u{2190}",
                    "rarr" => "\u{2192}",
                    "times" => "\u{d7}",
                    "divide" => "\u{f7}",
                    _ => return None,
                };
                return Some((j + 1, rep.to_string()));
            }
            return None;
        }
        if c.is_ascii_digit() {
            digits = true;
            j += 1;
            continue;
        }
        if c.is_ascii_alphabetic() {
            alpha = true;
            alpha_str.push(c);
            j += 1;
            continue;
        }
        return None;
    }
    None
}

pub fn parse_inline(s: &str) -> Vec<Inline> {
    parse_kind(s, Kind::Text)
}

pub fn parse_kind(s: &str, parent: Kind) -> Vec<Inline> {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut out: Vec<Inline> = Vec::new();
    let mut buf = String::new();
    let mut i = 0usize;
    macro_rules! flush {
        () => {
            if !buf.is_empty() {
                out.push(parent.to_type(std::mem::take(&mut buf)));
            }
        };
    }
    macro_rules! emit_delim {
        ($c:expr) => {
            flush!();
            out.push(Kind::Text.to_type($c.to_string()));
        };
    }
    while i < n {
        let c = chars[i];
        match c {
            '\\' => {
                flush!();
                if i + 1 < n {
                    buf.push(chars[i + 1]);
                    i += 2;
                } else {
                    buf.push('\\');
                    i += 1;
                }
                continue;
            }
            '!' if i + 1 < n && chars[i + 1] == '[' => {
                if let Some((end, alt, src)) = scan_image(&chars, i) {
                    flush!();
                    out.push(Inline::Image { alt, src, title: None });
                    i = end;
                    continue;
                }
                buf.push('!');
                i += 1;
                continue;
            }
            '[' => {
                if let Some((end, text, url)) = scan_link(&chars, i) {
                    flush!();
                    out.push(Inline::Link { text, url, title: None });
                    i = end;
                    continue;
                }
                emit_delim!('[');
                i += 1;
                continue;
            }
            '<' => {
                if let Some(end) = scan_html_tag(&chars, i) {
                    flush!();
                    i = end;
                    continue;
                }
                emit_delim!('<');
                i += 1;
                continue;
            }
            '&' => {
                if let Some((end, decoded)) = scan_entity(&chars, i) {
                    flush!();
                    out.push(Inline::Text { value: decoded });
                    i = end;
                    continue;
                }
                buf.push('&');
                i += 1;
                continue;
            }
            '`' => {
                if let Some((end, val)) = scan_code(&chars, i) {
                    flush!();
                    out.push(Inline::Code { value: val });
                    i = end;
                    continue;
                }
                emit_delim!('`');
                i += 1;
                continue;
            }
            '*' => {
                let run = run_of(&chars, i, c);
                if let Some((end, inner_start, inner_end)) = find_closer(&chars, i + run, c, run) {
                    flush!();
                    let inner: String = chars[inner_start..inner_end].iter().collect();
                    let k = if run >= 2 { Kind::Strong } else { Kind::Emphasis };
                    let sub = if k.rank() > parent.rank() { k } else { parent };
                    for e in parse_kind(&inner, sub) {
                        out.push(e);
                    }
                    i = end;
                    continue;
                }
                let prev_alnum = if i > 0 { chars[i - 1].is_alphanumeric() } else { false };
                let next_alnum = if i + run < n { chars[i + run].is_alphanumeric() } else { false };
                if prev_alnum || next_alnum {
                    for _ in 0..run {
                        emit_delim!('*');
                        i += 1;
                    }
                    continue;
                }
                for _ in 0..run {
                    buf.push('*');
                }
                i += run;
                continue;
            }
            '_' => {
                let run = run_of(&chars, i, c);
                if let Some((end, inner_start, inner_end)) = find_closer(&chars, i + run, c, run) {
                    flush!();
                    let inner: String = chars[inner_start..inner_end].iter().collect();
                    let k = if run >= 2 { Kind::Strong } else { Kind::Emphasis };
                    let sub = if k.rank() > parent.rank() { k } else { parent };
                    for e in parse_kind(&inner, sub) {
                        out.push(e);
                    }
                    i = end;
                    continue;
                }
                let prev_alnum = if i > 0 { chars[i - 1].is_alphanumeric() } else { false };
                let next_alnum = if i + run < n { chars[i + run].is_alphanumeric() } else { false };
                if prev_alnum != next_alnum {
                    for _ in 0..run {
                        emit_delim!('_');
                        i += 1;
                    }
                    continue;
                }
                for _ in 0..run {
                    buf.push('_');
                }
                i += run;
                continue;
            }
            '~' => {
                let run = run_of(&chars, i, c);
                if run >= 3 {
                    for _ in 0..run {
                        buf.push('~');
                    }
                    i += run;
                    continue;
                }
                if let Some((end, inner_start, inner_end)) = find_closer(&chars, i + run, c, run) {
                    flush!();
                    let inner: String = chars[inner_start..inner_end].iter().collect();
                    let k = Kind::Strike;
                    let sub = if k.rank() > parent.rank() { k } else { parent };
                    for e in parse_kind(&inner, sub) {
                        out.push(e);
                    }
                    i = end;
                    continue;
                }
                let prev_alnum = if i > 0 { chars[i - 1].is_alphanumeric() } else { false };
                let next_alnum = if i + run < n { chars[i + run].is_alphanumeric() } else { false };
                let split = if run == 2 { prev_alnum || next_alnum } else { prev_alnum != next_alnum || i + run >= n };
                if split {
                    for _ in 0..run {
                        emit_delim!('~');
                        i += 1;
                    }
                    continue;
                }
                for _ in 0..run {
                    buf.push('~');
                }
                i += run;
                continue;
            }
            _ => {
                buf.push(c);
                i += 1;
            }
        }
    }
    if !buf.is_empty() {
        out.push(parent.to_type(buf));
    }
    out
}
